		t.Fatal(err)
	}
	if err := syncTerraBase(t.Context(), state, root, feed.run, nil, io.Discard); err == nil || !strings.Contains(err.Error(), "assets changed") {
		t.Fatalf("changed source accepted on resume: %v", err)
	}
}

