func newCDTestFeed(t *testing.T) *cdTestFeed {
	t.Helper()
	return &cdTestFeed{t: t, releases: make(map[string]terrabaseReleaseFiles)}
}

func (feed *cdTestFeed) add(root, version string, runID uint64) string {
	feed.t.Helper()
	files := writeDeployTestRelease(feed.t, root, version)
	wire, err := os.ReadFile(files.Qualification)
	if err != nil {
		feed.t.Fatal(err)
	}
	var qualification map[string]any
	if err := json.Unmarshal(wire, &qualification); err != nil {
		feed.t.Fatal(err)
	}
	qualification["repository"] = "TerraScale/TerraBase"
	verification := qualification["verification"].(map[string]any)
	verification["run_id"], verification["run_number"], verification["job"] = runID, runID+1000, "fast"
	wire, err = json.Marshal(qualification)
	if err != nil {
		feed.t.Fatal(err)
	}
	if err := os.WriteFile(files.Qualification, wire, 0o600); err != nil {
		feed.t.Fatal(err)
	}
	var source terrabaseSourceDigest
	sourceWire, err := os.ReadFile(files.SourceDigest)
	if err != nil {
		feed.t.Fatal(err)
	}
	if err := json.Unmarshal(sourceWire, &source); err != nil {
		feed.t.Fatal(err)
	}
	sum := sha256.Sum256(wire)
	source.QualificationSHA256 = hex.EncodeToString(sum[:])
	sourceWire, err = json.Marshal(source)
	if err != nil {
		feed.t.Fatal(err)
	}
	if err := os.WriteFile(files.SourceDigest, sourceWire, 0o600); err != nil {
		feed.t.Fatal(err)
	}
	tag := fmt.Sprintf("ci-%s-run-%d", source.SourceRevision, runID)
	feed.releases[tag] = files
	feed.commits = append(feed.commits, source.SourceRevision)
	feed.listing = append(feed.listing, tag)
	return tag
}

func (feed *cdTestFeed) run(_ context.Context, name string, args ...string) ([]byte, error) {
	feed.calls++
	if name == "git" {
		switch args[2] {
		case "remote":
			return []byte(terrabaseSourceRepo + ".git\n"), nil
		case "fetch":
			return nil, nil
		case "merge-base":
			left, right := slices.Index(feed.commits, args[4]), slices.Index(feed.commits, args[5])
			if args[5] == "refs/remotes/origin/main" {
				right = len(feed.commits) - 1
			}
			if left < 0 || right < 0 || left > right {
				return nil, errCDNotAncestor
			}
			return nil, nil
		}
	}
	if name != "gh" {
		feed.t.Fatalf("unexpected command: %s %v", name, args)
	}
	if args[0] == "release" && args[1] == "list" {
		var releases []map[string]any
		for _, tag := range feed.listing {
			releases = append(releases, map[string]any{"tagName": tag, "isDraft": false, "isPrerelease": true})
		}
		return json.Marshal(releases)
	}
	if args[0] == "release" && args[1] == "download" {
		feed.downloads = append(feed.downloads, args[6])
		files := feed.releases[args[2]]
		source := map[string]string{"qualification.json": files.Qualification, terrabaseServerArtifact: files.Binary, "source-digest.json": files.SourceDigest}[args[6]]
		wire, err := os.ReadFile(source)
		if err != nil {
			return nil, err
		}
		return nil, os.WriteFile(args[8], wire, 0o600)
	}
	if args[0] == "api" {
		if len(args) < 4 || args[1] != "--hostname" || args[2] != "github.com" {
			feed.t.Fatalf("GitHub API hostname is not pinned: %v", args)
		}
		endpoint := args[len(args)-1]
		parts := strings.Split(endpoint, "/")
		id, err := strconv.ParseUint(parts[5], 10, 64)
		if err != nil {
			return nil, err
		}
		for tag, files := range feed.releases {
			match := cdTagPattern.FindStringSubmatch(tag)
			runID, _ := strconv.ParseUint(match[2], 10, 64)
			if runID != id {
				continue
			}
			if parts[4] == "runs" && len(parts) == 6 {
				status, conclusion := "completed", "success"
				if feed.badRun {
					status, conclusion = "in_progress", ""
				}
				return json.Marshal(map[string]any{"id": id, "run_number": id + 1000, "head_sha": match[1], "head_branch": "main", "event": "push",
					"path": ".github/workflows/fast.yml", "status": status, "conclusion": conclusion, "run_attempt": 1,
					"repository":      map[string]string{"full_name": terrabaseGitHubRepo},
					"head_repository": map[string]string{"full_name": terrabaseGitHubRepo}})
			}
			if parts[4] == "runs" && strings.Contains(endpoint, "/attempts/1/jobs") {
				return json.Marshal([]map[string]any{{"jobs": []map[string]any{
					{"id": 1, "run_id": id, "name": "fast", "status": "completed", "conclusion": "success", "run_attempt": 1},
					{"id": id, "run_id": id, "name": "publish", "status": "completed", "conclusion": "success", "run_attempt": 1}}}})
			}
			if parts[4] == "jobs" {
				if feed.badLog {
					return []byte("unrelated qualification"), nil
				}
				wire, err := os.ReadFile(files.Qualification)
				if err != nil {
					return nil, err
				}
				sum := sha256.Sum256(wire)
				return fmt.Appendf(nil, "2026-09-30T00:00:00Z TS_TERRABASE_QUALIFICATION_V2 source_sha=%s run_id=%d run_number=%d manifest_sha256=%x\n", match[1], id, id+1000, sum), nil
			}
		}
	}
	feed.t.Fatalf("unexpected command: %s %v", name, args)
	return nil, errors.New("unexpected command")
}

func cdTestState(t *testing.T, root string, files terrabaseReleaseFiles) string {
	t.Helper()
	statePath := filepath.Join(root, "state")
	state, err := openDeployState(statePath)
	if err != nil {
		t.Fatal(err)
	}
	release, err := loadTerraBaseRelease(files)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := state.ensureJSON(deployArtifactFile, delivery.ArtifactRecord{Digest: release.Digest, Source: release.Source}); err != nil {
		t.Fatal(err)
	}
	return statePath
}

func syncTerraBaseWithPolicy(ctx context.Context, statePath, checkout string, run cdRunCommand,
	update func(terrabaseReleaseFiles) error, output io.Writer, policy cdRetryPolicy,
) error {
	state, err := openDeployState(statePath)
	if err != nil {
		return err
	}
	// Lock the deployment, not a candidate: an overlapping timer must not
	// choose another release while the first is between its two seats.
	fd, err := syscall.Open(filepath.Join(statePath, "cd.lock"), syscall.O_CREAT|syscall.O_RDWR|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return err
	}
	lock := os.NewFile(uintptr(fd), "cd.lock")
	defer lock.Close()
	if err := syscall.Flock(fd, syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		return fmt.Errorf("another TerraBase sync holds this deployment: %w", err)
	}
	var blocked struct {
		Candidate terrabaseCDCandidate `json:"candidate"`
		Reason    string               `json:"reason"`
	}
	if exists, err := state.readJSON(cdBlockedFile, &blocked); err != nil {
		return err
	} else if exists {
		return fmt.Errorf("automatic rollout stopped for %s; review %s before resuming", blocked.Candidate.Tag, cdBlockedFile)
	}
	baseline, generation, err := cdBaseline(state)
	if err != nil {
		return err
	}
	var candidate terrabaseCDCandidate
	active, err := state.readJSON(cdActiveFile, &candidate)
	if err != nil {
		return err
	}
	if active && candidate.Generation == generation {
		// Completion was synced before a crash removing the active pin.
		var completed terrabaseCDCandidate
		_, err := state.readJSON(cdReceiptName(generation), &completed)
		if err != nil || completed != candidate {
			return errors.New("active release differs from its completion receipt")
		}
		return os.Remove(filepath.Join(statePath, cdActiveFile))
	}
	origin, err := run(ctx, "git", "-C", checkout, "remote", "get-url", "origin")
	if err != nil {
		return err
	}
	if url := strings.TrimSpace(string(origin)); !strings.EqualFold(url, terrabaseSourceRepo+".git") &&
		!strings.EqualFold(url, "ssh://git@github.com/TerraScale/TerraBase.git") &&
		!strings.EqualFold(url, "git@github.com:TerraScale/TerraBase.git") {
		return errors.New("TerraBase checkout origin differs from the reviewed repository")
	}
	if _, err := run(ctx, "git", "-C", checkout, "fetch", "origin", "main:refs/remotes/origin/main"); err != nil {
		return err
	}
	if _, err := run(ctx, "git", "-C", checkout, "merge-base", "--is-ancestor", baseline, "refs/remotes/origin/main"); err != nil {
		return fmt.Errorf("deployed TerraBase source is outside current main: %w", err)
	}
	if !active {
		candidate, err = discoverTerraBase(ctx, checkout, baseline, run)
		if err != nil {
			return err
		}
		if candidate.Tag == "" {
			return printJSON(output, terrabaseDeployStep{Step: "sync", Status: "current", Detail: baseline})
		}
		candidate.Generation = generation + 1
	}
	if candidate.Generation != generation+1 || !cdTagPattern.MatchString(candidate.Tag) ||
		candidate.Tag != fmt.Sprintf("ci-%s-run-%d", candidate.Commit, candidate.RunID) {
		return errors.New("invalid active continuous delivery pin")
	}
	if err := cdCheckAncestry(ctx, checkout, baseline, candidate.Commit, run); err != nil {
		return err
	}
	directory, err := os.MkdirTemp(statePath, ".cd-release-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(directory)
	files := terrabaseReleaseFiles{Qualification: filepath.Join(directory, "qualification.json"),
		Binary: filepath.Join(directory, terrabaseServerArtifact), SourceDigest: filepath.Join(directory, "source-digest.json")}
	download := func(path string) error {
		if _, err := run(ctx, "gh", "release", "download", candidate.Tag, "--repo", terrabaseGitHubRepo,
			"--pattern", filepath.Base(path), "--output", path); err != nil {
			return fmt.Errorf("download %s for %s: %w", filepath.Base(path), candidate.Tag, err)
		}
		return nil
	}
	// Check publication readiness before downloading the much larger server.
	for _, path := range []string{files.Qualification, files.SourceDigest} {
		if err := download(path); err != nil {
			return err
		}
	}
	if err := cdVerifyPublication(ctx, files.Qualification, candidate, run); err != nil {
		return err
	}
	if err := download(files.Binary); err != nil {
		return err
	}
	release, err := loadTerraBaseRelease(files)
	if err != nil {
		return err
	}
	if release.Source.Repository != terrabaseSourceRepo || release.Source.Commit != candidate.Commit || release.CIRunID != candidate.RunID {
		return errors.New("TerraBase release does not match its selected repository, commit and run")
	}
	verified := candidate
	verified.QualificationSHA256, verified.BinarySHA256, verified.SourceSHA256 = release.QualificationSHA256, release.Digest, release.Source.TreeDigest
	if active && verified != candidate {
		return errors.New("published TerraBase assets changed after the rollout was pinned")
	}
	candidate = verified
	if _, err := state.ensureJSON(cdActiveFile, candidate); err != nil {
		return err
	}
	if err := updateWithRetries(ctx, policy, func() error { return update(files) }, output); err != nil {
		// An explicit interruption resumes the same pin next invocation. An
		// expired --timeout is a transient failure of this run: it counts
		// toward --transient-block-after, or a timeout shorter than the
		// rollout would keep a mixed-version deployment from ever escalating.
		timedOut := errors.Is(ctx.Err(), context.DeadlineExceeded)
		if ctx.Err() != nil && !timedOut {
			return err
		}
		reason := err.Error()
		if timedOut {
			reason = "sync deadline expired: " + reason
		}
		if timedOut || staged.IsTransient(err) {
			// Keep the pin and resume it next run; escalate only once the
			// failure has outlived the bound.
			first, persistErr := cdTransientSince(state, candidate, reason)
			if persistErr != nil || time.Since(first) < policy.BlockAfter {
				return errors.Join(err, persistErr)
			}
			reason = fmt.Sprintf("transient failures persisted since %s: %s", first.Format(time.RFC3339), reason)
		}
		blocked.Candidate, blocked.Reason = candidate, reason
		_, persistErr := state.ensureJSON(cdBlockedFile, blocked)
		if persistErr == nil {
			// The stop marker carries the reason. Once a reviewer removes it,
			// a later transient failure starts a fresh window instead of
			// blocking again at once on this stale first failure.
			if removeErr := os.Remove(filepath.Join(statePath, cdTransientFile)); removeErr != nil && !errors.Is(removeErr, os.ErrNotExist) {
				persistErr = removeErr
			}
		}
		return errors.Join(err, persistErr)
	}
	if err := os.Remove(filepath.Join(statePath, cdTransientFile)); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	if _, err := state.ensureJSON(cdReceiptName(candidate.Generation), candidate); err != nil {
		return err
	}
	return os.Remove(filepath.Join(statePath, cdActiveFile))
}

func cdTransientSince(state deployState, candidate terrabaseCDCandidate, reason string) (time.Time, error) {
	var record cdTransientRecord
	exists, err := state.readJSON(cdTransientFile, &record)
	if err != nil {
		return time.Time{}, err
	}
	if exists && record.Candidate == candidate {
		return record.FirstAt, nil
	}
	if exists {
		if err := os.Remove(filepath.Join(state.directory, cdTransientFile)); err != nil {
			return time.Time{}, err
		}
	}
	record = cdTransientRecord{Candidate: candidate, FirstAt: time.Now().UTC(), Reason: reason}
	if _, err := state.readOrCreateJSON(cdTransientFile, record); err != nil {
		return time.Time{}, err
	}
	return record.FirstAt, nil
}

func cdReceiptName(generation uint64) string {
	return fmt.Sprintf("cd-complete-%020d.json", generation)
}

func cdBaseline(state deployState) (string, uint64, error) {
	var initial delivery.ArtifactRecord
	if exists, err := state.readJSON(deployArtifactFile, &initial); err != nil {
		return "", 0, err
	} else if !exists {
		return "", 0, errors.New("continuous delivery requires the existing deployment artifact record")
	}
	if initial.Source.Repository != terrabaseSourceRepo || !gitCommitPattern.MatchString(initial.Source.Commit) {
		return "", 0, errors.New("deployment artifact is not from the reviewed TerraBase repository")
	}
	entries, err := os.ReadDir(state.directory)
	if err != nil {
		return "", 0, err
	}
	baseline, generation := initial.Source.Commit, uint64(0)
	for _, entry := range entries { // ReadDir sorts immutable receipt names.
		if !cdReceiptPattern.MatchString(entry.Name()) {
			continue
		}
		var completed terrabaseCDCandidate
		if _, err := state.readJSON(entry.Name(), &completed); err != nil {
			return "", 0, err
		}
		if completed.Generation != generation+1 || entry.Name() != cdReceiptName(completed.Generation) ||
			!gitCommitPattern.MatchString(completed.Commit) {
			return "", 0, errors.New("continuous delivery completion receipts are not a contiguous sequence")
		}
		baseline, generation = completed.Commit, completed.Generation
	}
	return baseline, generation, nil
}

func discoverTerraBase(ctx context.Context, checkout, baseline string, run cdRunCommand) (terrabaseCDCandidate, error) {
	listing, err := run(ctx, "gh", "release", "list", "--repo", terrabaseGitHubRepo, "--json", "tagName,isDraft,isPrerelease", "--limit", "100")
	if err != nil {
		return terrabaseCDCandidate{}, err
	}
	var releases []struct {
		TagName      string `json:"tagName"`
		IsDraft      bool   `json:"isDraft"`
		IsPrerelease bool   `json:"isPrerelease"`
	}
	if err := json.Unmarshal(listing, &releases); err != nil {
		return terrabaseCDCandidate{}, err
	}
	var selected terrabaseCDCandidate
	for _, release := range releases {
		if release.IsDraft {
			continue
		}
		match := cdTagPattern.FindStringSubmatch(release.TagName)
		if match == nil || match[1] == baseline {
			continue
		}
		runID, err := strconv.ParseUint(match[2], 10, 64)
		if err != nil {
			return selected, err
		}
		candidate := terrabaseCDCandidate{Tag: match[0], Commit: match[1], RunID: runID}
		if err := cdCheckAncestry(ctx, checkout, baseline, candidate.Commit, run); err != nil {
			// A rerun of old source, a side branch, or an unfetched release
			// cannot become an automatic downgrade.
			if errors.Is(err, errCDNotAncestor) {
				continue
			}
			return selected, err
		}
		if selected.Tag != "" {
			if selected.Commit == candidate.Commit && selected.RunID >= candidate.RunID {
				continue
			}
			if _, err := run(ctx, "git", "-C", checkout, "merge-base", "--is-ancestor", selected.Commit, candidate.Commit); err != nil {
				if errors.Is(err, errCDNotAncestor) {
					continue
				}
				return selected, err
			}
		}
		selected = candidate
	}
	return selected, nil
}

func cdCheckAncestry(ctx context.Context, checkout, baseline, candidate string, run cdRunCommand) error {
	for _, pair := range [][2]string{{baseline, candidate}, {candidate, "refs/remotes/origin/main"}} {
		if _, err := run(ctx, "git", "-C", checkout, "merge-base", "--is-ancestor", pair[0], pair[1]); err != nil {
			return fmt.Errorf("TerraBase source is outside the current main lineage: %w", err)
		}
	}
	return nil
}

func cdVerifyPublication(ctx context.Context, path string, candidate terrabaseCDCandidate, run cdRunCommand) error {
	wire, err := readBoundedConfigFile(path)
	if err != nil {
		return err
	}
	var qualification struct {
		Repository   string `json:"repository"`
		Verification struct {
			Workflow  string `json:"workflow"`
			Job       string `json:"job"`
			RunNumber uint64 `json:"run_number"`
			RunID     uint64 `json:"run_id"`
		} `json:"verification"`
	}
	if err := json.Unmarshal(wire, &qualification); err != nil {
		return err
	}
	if qualification.Repository != "TerraScale/TerraBase" || qualification.Verification.Workflow != "fast.yml" ||
		qualification.Verification.Job != "fast" || qualification.Verification.RunNumber == 0 ||
		qualification.Verification.RunID != candidate.RunID {
		return errors.New("automatic TerraBase delivery requires a Fast-qualified publication")
	}
	detailWire, err := githubapi.RunDetail(terrabaseGitHubRepo, int64(candidate.RunID), func(args ...string) ([]byte, error) {
		return run(ctx, "gh", args...)
	})
	if err != nil {
		return err
	}
	var detail struct {
		RunID     uint64 `json:"run_id"`
		RunNumber uint64 `json:"run_number"`
		HeadSHA   string `json:"head_sha"`
		Workflow  string `json:"workflow"`
		Status    string `json:"status"`
		Jobs      []struct {
			ID     uint64 `json:"id"`
			RunID  uint64 `json:"run_id"`
			Name   string `json:"name"`
			Status string `json:"status"`
		} `json:"jobs"`
	}
	if err := json.Unmarshal(detailWire, &detail); err != nil {
		return err
	}
	if detail.RunID != candidate.RunID || detail.RunNumber != qualification.Verification.RunNumber ||
		detail.HeadSHA != candidate.Commit || detail.Workflow != "fast.yml" || detail.Status != "success" {
		return errors.New("TerraBase publication run differs from its qualification or is not successful")
	}
	fast, publish, publishID := 0, 0, uint64(0)
	for _, job := range detail.Jobs {
		if job.RunID == candidate.RunID && job.Status == "success" && job.ID != 0 {
			switch job.Name {
			case "fast":
				fast++
			case "publish":
				publish++
				publishID = job.ID
			}
		}
	}
	if fast != 1 || publish != 1 {
		return errors.New("TerraBase publication lacks exactly one successful Fast and publish job")
	}
	logs, err := run(ctx, "gh", "api", "--hostname", "github.com", fmt.Sprintf("repos/%s/actions/jobs/%d/logs", terrabaseGitHubRepo, publishID))
	if err != nil {
		return err
	}
	sum := sha256.Sum256(wire)
	marker := fmt.Sprintf("TS_TERRABASE_QUALIFICATION_V2 source_sha=%s run_id=%d run_number=%d manifest_sha256=%x",
		candidate.Commit, candidate.RunID, detail.RunNumber, sum)
	if strings.Count(string(logs), marker) != 1 {
		return errors.New("TerraBase publish log does not bind the exact qualification bytes")
	}
	return nil
}

// openDeployState creates or reopens an owner-only state directory.
func openDeployState(path string) (deployState, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return deployState{}, errors.New("--state must be a clean absolute directory")
	}
	if err := os.Mkdir(path, 0o700); err != nil && !errors.Is(err, os.ErrExist) {
		return deployState{}, err
	}
	for _, directory := range []string{path, filepath.Join(path, deployCustomerDirectory),
		filepath.Join(path, deployReleaseDirectory), filepath.Join(path, deployKnownBadDirectory)} {
		if err := os.Mkdir(directory, 0o700); err != nil && !errors.Is(err, os.ErrExist) {
			return deployState{}, err
		}
		info, err := os.Lstat(directory)
		if err != nil {
			return deployState{}, err
		}
		stat, ok := info.Sys().(*syscall.Stat_t)
		if !info.IsDir() || info.Mode().Perm() != 0o700 || !ok || stat.Uid != uint32(os.Getuid()) {
			return deployState{}, fmt.Errorf("%s must be an owner-only directory of this user", directory)
		}
	}
	return deployState{directory: path}, nil
}

func (state deployState) readJSON(name string, value any) (bool, error) {
	data, err := state.readFile(name)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	if err := json.Unmarshal(data, value, json.RejectUnknownMembers(true)); err != nil {
		return false, fmt.Errorf("decode retained %s: %w", name, err)
	}
	return true, nil
}

func (state deployState) readFile(name string) ([]byte, error) {
	fd, err := syscall.Open(filepath.Join(state.directory, name), syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: name, Err: err}
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 || info.Size() > maxDeployStateFileBytes {
		return nil, fmt.Errorf("retained %s must be a bounded owner-only file", name)
	}
	return io.ReadAll(io.LimitReader(file, maxDeployStateFileBytes+1))
}

// ensureJSON creates a canonical state file or requires the retained file to
// hold exactly the same bytes. It reports whether the file was created.
func (state deployState) ensureJSON(name string, value any) (bool, error) {
	wire, err := protocol.EncodeJSON(value)
	if err != nil {
		return false, err
	}
	existing, err := state.readFile(name)
	if err == nil {
		if !bytes.Equal(existing, wire) {
			return false, fmt.Errorf("retained %s differs from this plan; use a new --state and partition to deploy a different plan", name)
		}
		return false, nil
	}
	if !errors.Is(err, os.ErrNotExist) {
		return false, err
	}
	return true, state.createFile(name, wire)
}

// readOrCreateJSON keeps the first retained value of an observation, such as
// an admission receipt whose sequence can differ on an idempotent replay.
func (state deployState) readOrCreateJSON(name string, value any) (bool, error) {
	if _, err := state.readFile(name); err == nil {
		return false, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return false, err
	}
	wire, err := protocol.EncodeJSON(value)
	if err != nil {
		return false, err
	}
	return true, state.createFile(name, wire)
}

// createFile publishes complete bytes through a synced temporary file and a
// create-only link, so an interrupted run never leaves a partial state file.
func (state deployState) createFile(name string, contents []byte) error {
	target := filepath.Join(state.directory, name)
	file, err := os.CreateTemp(filepath.Dir(target), ".ts-deploy-*")
	if err != nil {
		return err
	}
	temporary := file.Name()
	defer os.Remove(temporary)
	if err := file.Chmod(0o600); err != nil {
		_ = file.Close()
		return err
	}
	if _, err := file.Write(contents); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Link(temporary, target); err != nil {
		return fmt.Errorf("publish %s without overwrite: %w", name, err)
	}
	directory, err := os.Open(filepath.Dir(target))
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

func updateWithRetries(ctx context.Context, policy cdRetryPolicy, update func() error, output io.Writer) error {
	sleep := policy.sleep
	if sleep == nil {
		sleep = sleepContext
	}
	for attempt := 1; ; attempt++ {
		err := update()
		if err == nil || ctx.Err() != nil || !staged.IsTransient(err) {
			return err
		}
		delay, retry := policy.Backoff.Delay(attempt)
		if !retry {
			return err
		}
		if printErr := printJSON(output, terrabaseDeployStep{Step: "sync", Status: "retrying",
			Detail: fmt.Sprintf("attempt %d after %s: %v", attempt+1, delay, err)}); printErr != nil {
			return errors.Join(err, printErr)
		}
		if sleepErr := sleep(ctx, delay); sleepErr != nil {
			return errors.Join(err, sleepErr)
		}
	}
}

func sleepContext(ctx context.Context, delay time.Duration) error {
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

func IsTransient(err error) bool { return err != nil && Classify(err) == ClassTransient }

// Backoff is a bounded exponential retry schedule.
type Backoff struct {
	Initial  time.Duration
	Max      time.Duration
	Attempts int
}

// Delay returns the wait before retry attempt (1-based) and whether that
// attempt is still allowed.
func (b Backoff) Delay(attempt int) (time.Duration, bool) {
	if attempt < 1 || attempt > b.Attempts || b.Initial <= 0 {
		return 0, false
	}
	delay := b.Initial
	for range attempt - 1 {
		// Without a cap the doubling would overflow into a negative delay;
		// saturate instead so a long schedule never collapses to no wait.
		if delay > math.MaxInt64/2 {
			delay = math.MaxInt64
		} else {
			delay *= 2
		}
		if b.Max > 0 && delay >= b.Max {
			return b.Max, true
		}
	}
	if b.Max > 0 && delay > b.Max {
		delay = b.Max
	}
	return delay, true
}

func runTerraBaseSync(ctx context.Context, args []string, output io.Writer) error {
	flags := flag.NewFlagSet("operator terrabase-sync", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	config := flags.String("config", "", "operator role configuration")
	statePath := flags.String("state", "", "existing owner-only deployment state")
	checkout := flags.String("source-checkout", "", "full TerraBase checkout with the reviewed origin")
	actor := flags.String("compatibility-actor", "", "trusted compatibility signer actor")
	key := flags.String("compatibility-key", "", "owner-only compatibility signer key")
	wait := flags.Duration("wait", defaultUpdateSeatWait, "outcome wait per seat")
	soak := flags.Duration("soak", staged.DefaultSoak, "how long a promoted seat must keep serving before the next seat (0 disables)")
	assumeCompatible := flags.Bool("assume-compatibility", false, "certify releases without a compatibility declaration as compatible (unverified)")
	retries := flags.Int("transient-retries", defaultCDRetryPolicy.Backoff.Attempts, "in-run retries of a transient rollout failure")
	blockAfter := flags.Duration("transient-block-after", defaultCDRetryPolicy.BlockAfter, "block for review once transient failures persist this long")
	timeout := flags.Duration("timeout", time.Hour, "total scan/rollout deadline")
	var forwards operatorForwardFlags
	flags.Var(&forwards, "nats-forward", "PRIVATE_IP:4222=LOOPBACK_IP:PORT (repeatable)")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if flags.NArg() != 0 || *config == "" || *statePath == "" || !filepath.IsAbs(*checkout) ||
		*actor == "" || *key == "" || *wait <= 0 || *timeout <= 0 || *soak < 0 || *retries < 0 || *blockAfter <= 0 {
		return errors.New("terrabase-sync requires --config, --state, --source-checkout, --compatibility-actor, --compatibility-key and positive deadlines")
	}
	ctx, cancel := context.WithTimeout(ctx, *timeout)
	defer cancel()
	update := func(files terrabaseReleaseFiles) error {
		updateArgs := []string{"terrabase-update", "--config", *config, "--state", *statePath,
			"--qualification", files.Qualification, "--binary", files.Binary, "--source-digest", files.SourceDigest,
			"--compatibility-actor", *actor, "--compatibility-key", *key, "--wait", wait.String(), "--soak", soak.String()}
		if *assumeCompatible {
			updateArgs = append(updateArgs, "--assume-compatibility")
		}
		for original, destination := range forwards {
			updateArgs = append(updateArgs, "--nats-forward", original+"="+destination)
		}
		return runOperator(ctx, updateArgs, output)
	}
	policy := defaultCDRetryPolicy
	policy.Backoff.Attempts, policy.BlockAfter = *retries, *blockAfter
	return syncTerraBaseWithPolicy(ctx, *statePath, *checkout, cdCommand, update, output, policy)
}

type cdRunCommand func(context.Context, string, ...string) ([]byte, error)

// Bound subprocess output too: a broken CLI or huge job log cannot exhaust
// the operator. Private credentials stay in GitHub CLI authentication, never arguments.
type cdCommandOutput struct{ buffer bytes.Buffer }

func (out *cdCommandOutput) Write(data []byte) (int, error) {
	if out.buffer.Len()+len(data) > 8<<20 {
		return 0, errors.New("continuous delivery command output exceeds 8 MiB")
	}
	return out.buffer.Write(data)
}

func cdCommand(ctx context.Context, name string, args ...string) ([]byte, error) {
	command := exec.CommandContext(ctx, name, args...)
	command.WaitDelay = time.Second
	var output cdCommandOutput
	command.Stdout = &output
	command.Stderr = io.Discard
	if err := command.Run(); err != nil {
		if exit, ok := errors.AsType[*exec.ExitError](err); ok && name == "git" &&
			len(args) > 2 && args[2] == "merge-base" && exit.ExitCode() == 1 {
			return nil, errCDNotAncestor
		}
		return nil, fmt.Errorf("%s continuous delivery command failed: %w", name, err)
	}
	return output.buffer.Bytes(), nil
}

func syncTerraBase(ctx context.Context, statePath, checkout string, run cdRunCommand,
	update func(terrabaseReleaseFiles) error, output io.Writer,
) error {
	return syncTerraBaseWithPolicy(ctx, statePath, checkout, run, update, output, defaultCDRetryPolicy)
}

// writeDeployTestRelease writes one retained TerraBase CI release whose
// server bytes and source revision are derived from version.
func writeDeployTestRelease(t *testing.T, root, version string) terrabaseReleaseFiles {
	t.Helper()
	directory := filepath.Join(root, "release-"+version)
	if err := os.MkdirAll(directory, 0o755); err != nil {
		t.Fatal(err)
	}
	binary := bytes.Repeat([]byte("tb-server-linux-arm64 release "+version+" "), 64)
	binaryPath := filepath.Join(directory, "tb-server-linux-arm64")
	if err := os.WriteFile(binaryPath, binary, 0o755); err != nil {
		t.Fatal(err)
	}
	binarySum := sha256.Sum256(binary)
	commitSum := sha256.Sum256([]byte("commit " + version))
	commit := hex.EncodeToString(commitSum[:20])
	fields := map[string]any{"schema": terrabaseQualificationSchema, "source_revision": commit,
		"artifacts": []map[string]any{{"name": terrabaseServerArtifact, "bytes": len(binary),
			"sha256": hex.EncodeToString(binarySum[:]), "target": terrabaseServerTarget}},
		"verification": map[string]any{"conclusion": "success", "run_id": 11696, "workflow": "fast.yml"}}
	if compatibility := deployTestCompatibility(version); compatibility != nil {
		fields["compatibility"] = compatibility
	}
	qualification, err := json.Marshal(fields)
	if err != nil {
		t.Fatal(err)
	}
	qualificationPath := filepath.Join(directory, "qualification.json")
	if err := os.WriteFile(qualificationPath, qualification, 0o644); err != nil {
		t.Fatal(err)
	}
	qualificationSum := sha256.Sum256(qualification)
	sourceSum := sha256.Sum256([]byte("source " + version))
	sourcePath := testJSONFile(t, directory, "source-digest.json", map[string]any{"schema": terrabaseSourceDigestSchema,
		"repository": deployTestRepository, "source_revision": commit, "source_digest_sha256": hex.EncodeToString(sourceSum[:]),
		"qualification_sha256": hex.EncodeToString(qualificationSum[:]), "server_linux_arm64_sha256": hex.EncodeToString(binarySum[:])})
	return terrabaseReleaseFiles{Qualification: qualificationPath, Binary: binaryPath, SourceDigest: sourcePath}
}

// deployTestCompatibility declares every test release mutually compatible
// unless its version names an incompatible persistent format.
func deployTestCompatibility(version string) map[string]any {
	format := 1
	if strings.HasPrefix(version, "format-break") {
		format = 9
	}
	if strings.HasPrefix(version, "no-compat") {
		return nil
	}
	capability := func(version int) map[string]any {
		return map[string]any{"version": version, "accepts": map[string]any{"min": version, "max": version}}
	}
	return map[string]any{"schema": staged.CompatibilitySchema, "persistent_format": capability(format),
		"replication": capability(1), "client_data": capability(1)}
}

func loadTerraBaseRelease(files terrabaseReleaseFiles) (terrabaseRelease, error) {
	qualificationWire, err := readBoundedConfigFile(files.Qualification)
	if err != nil {
		return terrabaseRelease{}, fmt.Errorf("read TerraBase qualification: %w", err)
	}
	var qualification terrabaseQualification
	if err := json.Unmarshal(qualificationWire, &qualification); err != nil {
		return terrabaseRelease{}, fmt.Errorf("decode TerraBase qualification: %w", err)
	}
	if qualification.Schema != terrabaseQualificationSchema || !gitCommitPattern.MatchString(qualification.SourceRevision) ||
		qualification.Verification.Conclusion != "success" || qualification.Verification.RunID == 0 {
		return terrabaseRelease{}, errors.New("TerraBase qualification is not a successful v2 CI record")
	}
	qualificationSum := sha256.Sum256(qualificationWire)
	digestWire, err := readBoundedConfigFile(files.SourceDigest)
	if err != nil {
		return terrabaseRelease{}, fmt.Errorf("read TerraBase source digest: %w", err)
	}
	var source terrabaseSourceDigest
	if err := json.Unmarshal(digestWire, &source); err != nil {
		return terrabaseRelease{}, fmt.Errorf("decode TerraBase source digest: %w", err)
	}
	digest, size, err := digestReleaseBinary(files.Binary)
	if err != nil {
		return terrabaseRelease{}, err
	}
	matches := 0
	for _, artifact := range qualification.Artifacts {
		if artifact.Name != terrabaseServerArtifact {
			continue
		}
		matches++
		if artifact.Target != terrabaseServerTarget || artifact.Bytes != size || artifact.SHA256 != digest {
			return terrabaseRelease{}, errors.New("TerraBase server bytes differ from the qualification manifest")
		}
	}
	if matches != 1 {
		return terrabaseRelease{}, errors.New("TerraBase qualification lacks exactly one ARM64 server artifact")
	}
	release := terrabaseRelease{Binary: files.Binary, Digest: digest, Size: size,
		Source: delivery.ArtifactSource{Repository: source.Repository, Commit: qualification.SourceRevision,
			TreeDigest: source.SourceDigestSHA256},
		QualificationSHA256: hex.EncodeToString(qualificationSum[:]), CIRunID: qualification.Verification.RunID,
		Compatibility: qualification.Compatibility}
	if release.Compatibility != nil {
		if err := release.Compatibility.Validate(); err != nil {
			return terrabaseRelease{}, fmt.Errorf("TerraBase qualification: %w", err)
		}
	}
	if source.Schema != terrabaseSourceDigestSchema || source.SourceRevision != qualification.SourceRevision ||
		source.QualificationSHA256 != release.QualificationSHA256 || source.ServerSHA256 != digest ||
		!fingerprintPattern.MatchString(source.SourceDigestSHA256) {
		return terrabaseRelease{}, errors.New("TerraBase source digest does not bind this qualification and server")
	}
	return release, nil
}

func digestReleaseBinary(path string) (string, int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", 0, fmt.Errorf("open TerraBase server: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > delivery.MaxArtifactBytes {
		return "", 0, errors.New("TerraBase server must be a bounded regular file")
	}
	hash := sha256.New()
	size, err := io.Copy(hash, io.LimitReader(file, delivery.MaxArtifactBytes+1))
	if err != nil || size != info.Size() {
		return "", 0, errors.New("TerraBase server changed while it was hashed")
	}
	return hex.EncodeToString(hash.Sum(nil)), size, nil
}

// releaseCompatibilityName is the retained compatibility declaration of one
// admitted release, kept so a later update or rollback can assess it.
func releaseCompatibilityName(digest string) string {
	return filepath.Join(deployReleaseDirectory, digest+".compatibility.json")
}

// retainReleaseCompatibility keeps the release's qualified declaration next
// to its admitted artifact record. A release without one keeps nothing.
func retainReleaseCompatibility(state deployState, release terrabaseRelease) error {
	if release.Compatibility == nil {
		return nil
	}
	_, err := state.ensureJSON(releaseCompatibilityName(release.Digest), *release.Compatibility)
	return err
}

// releaseCompatibility loads a retained declaration; ok is false when the
// release never published one.
func releaseCompatibility(state deployState, digest string) (rollout.CompatibilityDeclaration, bool, error) {
	var declaration rollout.CompatibilityDeclaration
	exists, err := state.readJSON(releaseCompatibilityName(digest), &declaration)
	return declaration, exists, err

