	t.Helper()
	ctx, cancel := context.WithCancel(t.Context())
	var done []chan error
	for _, seat := range []string{"000000000082AXF7GZQT1D126Y", "0000000000XG8SBD7XGE97V28G"} {
		member, err := cell.store.ReadMember(ctx, intent.DatabaseID, intent.PartitionID, seat)
