func operatorArtifactPush(ctx context.Context, cfg Config, runtime *natscell.Runtime, path string, claim delivery.ArtifactClaimRequest, output io.Writer) error {
	record, err := pushArtifact(ctx, cfg, runtime, path, claim)
	if err != nil {
		return err
	}
	return printJSON(output, record)
}

// pushArtifact stores the exact file bytes in the regional artifact store and
// requests their signed admission. Both effects are idempotent for one digest
// and claim, so reruns re-confirm an already admitted artifact.
func pushArtifact(ctx context.Context, cfg Config, runtime *natscell.Runtime, path string, claim delivery.ArtifactClaimRequest) (delivery.ArtifactRecord, error) {
	service, activeRuntime, err := bindArtifactPushClient(ctx, cfg, runtime)
	if activeRuntime != nil && activeRuntime != runtime {
		defer activeRuntime.Close()
	}
	if err != nil {
		return delivery.ArtifactRecord{}, err
	}
	file, err := os.Open(path)
	if err != nil {
		return delivery.ArtifactRecord{}, err
	}
	defer file.Close()
	record, signedClaim, err := service.PrepareArtifact(ctx, file, claim)
	if err != nil {
		return delivery.ArtifactRecord{}, err
	}
	if err := requestArtifactAdmission(ctx, activeRuntime.Conn(), cfg.NATS.Cell, record, signedClaim); err != nil {
		return delivery.ArtifactRecord{}, err
	}
	return record, nil
}

func requestArtifactAdmission(ctx context.Context, conn *nats.Conn, cell string, record delivery.ArtifactRecord, signedClaim []byte) error {
	recoveryCtx, cancel := context.WithTimeout(ctx, operatorAdmissionRecoveryTimeout)
	defer cancel()
	backoff := operatorRetryInitialBackoff
	for {
		if err := recoveryCtx.Err(); err != nil {
			return err
		}
		requestCtx, stop := context.WithTimeout(recoveryCtx, operatorAdmissionAttemptTimeout)
		message, requestErr := conn.RequestWithContext(requestCtx, delivery.ArtifactClaimSubject(cell), signedClaim)
		attemptTimedOut := errors.Is(requestCtx.Err(), context.DeadlineExceeded)
		stop()
		if requestErr == nil {
			var response artifactAdmissionResponse
			if err := json.Unmarshal(message.Data, &response, json.RejectUnknownMembers(true)); err != nil {
				return fmt.Errorf("decode artifact admission reply: %w", err)
			}
			if response.Error == "" {
				if response.Retryable {
					return errors.New("controller returned a retryable artifact admission success")
				}
				if response.Record != record {
					return errors.New("controller admitted a different artifact record")
				}
				return nil
			}
			if !response.Retryable {
				return errors.New(response.Error)
			}
			requestErr = fmt.Errorf("%w: %s", errControllerRetryable, response.Error)
		} else if !retryableOperatorBackendError(requestErr, attemptTimedOut) {
			return fmt.Errorf("request controller artifact admission: %w", requestErr)
		}
		if err := waitOperatorRetry(recoveryCtx, backoff); err != nil {
			if ctx.Err() != nil {
				return ctx.Err()
			}
			return fmt.Errorf("request controller artifact admission: %w", requestErr)
		}
		backoff = min(backoff*2, operatorRetryMaxBackoff)
	}
}

// A timed-out resource bind may leave its NATS request multiplexer unhealthy.
// A typed transient metadata error can use the current connection. Both cases
// are bounded by the existing 5-second attempt and 15-second total bind times.
func bindArtifactPushClient(ctx context.Context, cfg Config, initial *natscell.Runtime) (*delivery.Service, *natscell.Runtime, error) {
	return bindArtifactPushClientWith(ctx, cfg, initial, operatorService)

func serveArtifactAdmission(ctx context.Context, conn *nats.Conn, cell string, fencer authority.Fencer, service *delivery.Service) (*nats.Subscription, error) {
	return conn.Subscribe(delivery.ArtifactClaimSubject(cell), func(message *nats.Msg) {
		if message.Reply == "" || len(message.Data) == 0 || len(message.Data) > delivery.MaxArtifactClaimBytes || !fencer.Current().CanMutate() {
			return
		}
		requestCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
		defer cancel()
		if err := fencer.Guard(requestCtx, fencer.Current().Epoch); err != nil {
			return
		}
		record, err := service.AcceptArtifactClaim(requestCtx, message.Data)
		if !fencer.Current().CanMutate() || fencer.Guard(requestCtx, fencer.Current().Epoch) != nil {
			return
		}
		response := artifactAdmissionResponse{Record: record}
		if err != nil {
			response.Record = delivery.ArtifactRecord{}
			response.Error = err.Error()
			response.Retryable = retryableOperatorBackendError(err, false)
		}
		wire, err := json.Marshal(response)
		if err == nil {
			_ = message.Respond(wire)
		}
	})
}

func (s *Service) PrepareArtifact(ctx context.Context, reader io.ReadSeeker, request ArtifactClaimRequest) (record ArtifactRecord, claim []byte, resultErr error) {
	if s == nil || reader == nil {
		return ArtifactRecord{}, nil, fmt.Errorf("%w: missing artifact reader", ErrInvalid)
	}
	if err := request.validate(); err != nil || request.Cell != s.config.Cell {
		return ArtifactRecord{}, nil, fmt.Errorf("%w: artifact target or source", ErrInvalid)
	}
	if s.config.ArtifactSigner == nil {
		return ArtifactRecord{}, nil, errors.New("artifact signer is not configured")
	}
	snapshot, size, digest, err := stageArtifact(ctx, reader)
	if err != nil {
		return ArtifactRecord{}, nil, err
	}
	defer func() {
		cleanupErr := discardStagedArtifact(snapshot)
		if cleanupErr != nil {
			if resultErr == nil {
				record = ArtifactRecord{}
				claim = nil
			}
			resultErr = errors.Join(resultErr, cleanupErr)
		}
	}()
	if size == 0 || size > MaxArtifactBytes {
		return ArtifactRecord{}, nil, fmt.Errorf("%w: artifact size must be 1..%d bytes", ErrInvalid, MaxArtifactBytes)
	}
	r := ArtifactRecord{SchemaVersion: SchemaVersion, Digest: digest, Source: request.Source, Cell: request.Cell, Role: request.Role, Environment: request.Environment, Size: size}
	r.ManifestDigest, err = r.calculatedManifestDigest()
	if err != nil {
		return ArtifactRecord{}, nil, err
	}
	if err := s.storeArtifact(ctx, snapshot, r); err != nil {
		return ArtifactRecord{}, nil, err
	}
	// Sign only after the bytes are stored: the claim's short validity must
	// cover its admission, not an upload over a slow operator link.
	envelope, err := s.config.ArtifactSigner.SignArtifact(ctx, r)
	if err != nil {
		return ArtifactRecord{}, nil, fmt.Errorf("sign artifact claim: %w", err)
	}
	return r, envelope, nil
}

// storeArtifact stores the staged bytes of r unless the store already holds
// them, and checks the stored object against r.
func (s *Service) storeArtifact(ctx context.Context, snapshot *os.File, r ArtifactRecord) error {
	exists, err := s.artifactExistsForUpload(ctx, r)
	if err != nil {
		return err
	}
	if exists {
		return nil
	}
	if _, err := snapshot.Seek(0, io.SeekStart); err != nil {
		return err
	}
	// Without a deadline every chunk ack gets only the JetStream default
	// timeout, which a slow operator link such as a bastion forward misses.
	uploadCtx, cancel := context.WithTimeout(ctx, artifactUploadTimeout)
	defer cancel()
	if _, err := s.artifacts.Put(uploadCtx, jetstream.ObjectMeta{Name: artifactKey(r.Digest)}, contextReader{uploadCtx, snapshot}); err != nil {
		if isArtifactStoreFullError(err) {
			return fmt.Errorf("store artifact: %w: %w", ErrArtifactStoreFull, err)
		}
		return fmt.Errorf("store artifact: %w", err)
	}
	return s.verifyArtifact(ctx, r)
}

// AdmitClaim is the controller's in-process admission of an artifact that

func (s *Service) AcceptArtifactClaim(ctx context.Context, envelope []byte) (ArtifactRecord, error) {
	if s == nil || s.config.ArtifactVerifier == nil || s.config.AuthorizeArtifact == nil || len(envelope) == 0 || len(envelope) > MaxArtifactClaimBytes {
		return ArtifactRecord{}, fmt.Errorf("%w: artifact admission configuration or signed claim", ErrInvalid)
	}
	r, actor, err := s.config.ArtifactVerifier.VerifyArtifact(ctx, envelope)
	if err != nil || actor == "" || r.validate() != nil || r.Cell != s.config.Cell {
		return ArtifactRecord{}, fmt.Errorf("%w: artifact signature or cell", ErrInvalid)
	}
	if err := s.config.AuthorizeArtifact(ctx, actor, r); err != nil {
		return ArtifactRecord{}, err
	}
	// A collector that chose the object before this admission can no
	// longer delete it.
	if err := s.touchArtifact(ctx, r.Digest); err != nil {
		return ArtifactRecord{}, err
	}
	if err := s.verifyArtifact(ctx, r); err != nil {
		return ArtifactRecord{}, err
	}
	if err := s.persistArtifactAdmission(ctx, r, envelope, actor); err != nil {
		return ArtifactRecord{}, err
	}
	return r, nil
}

