			_ = message.Respond(wire)
		}
	})

func verifyAndApplyPlacement(ctx context.Context, wire []byte, cell string, policy signerPolicy, control placementAdmissionControl, material ...placementMaterialAdmission) (placementApplyResponse, error) {
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(wire, &envelope, maxPlacementWireBytes); err != nil {
		return placementApplyResponse{}, err
	}
	var intent placement.Intent
	if err := protocol.DecodeStrict(envelope.Payload, &intent, maxPlacementIntentBytes); err != nil {
		return placementApplyResponse{}, err
	}
	if err := intent.ValidateForAdmission(); err != nil {
		return placementApplyResponse{}, err
	}
	if !intentSelectsCell(intent, cell) {
		return placementApplyResponse{}, errors.New("placement intent does not select this regional cell")
	}
	grant, exists := policy.grant(envelope.Actor)
	if !exists || !grant.CanPlaceTerraBase {
		return placementApplyResponse{}, errors.New("placement actor is unauthorized")
	}
	trusted, exists := policy.trusted(envelope.KeyID)
	if !exists || trusted.Actor != envelope.Actor {
		return placementApplyResponse{}, errors.New("placement signing key is untrusted")
	}
	if err := protocol.VerifyEnvelope(envelope, protocol.EnvelopeScope{
		Region: cell, Kind: managedKindPlacement, Actor: trusted.Actor,
		OperationID: placementOperationID(intent), Generation: intent.Generation, Epoch: envelope.Epoch,
	}, trusted.PublicKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: 5 * time.Minute, ClockSkew: 30 * time.Second}); err != nil {
		return placementApplyResponse{}, err
	}
	if envelope.Epoch == 0 || control.Current().Epoch != envelope.Epoch {
		return placementApplyResponse{}, authority.ErrFenced
	}
	payload, err := protocol.EncodeJSON(intent)
	if err != nil {
		return placementApplyResponse{}, err
	}
	if !bytes.Equal(envelope.Payload, payload) {
		return placementApplyResponse{}, errors.New("signed placement payload is not canonical")
	}
	if len(material) > 1 {
		return placementApplyResponse{}, errors.New("multiple managed material verifiers")
	}
	if len(material) == 1 {
		if material[0] == nil {
			return placementApplyResponse{}, errors.New("managed material verifier is unavailable")
		}
		if err := material[0](ctx, intent); err != nil {
			return placementApplyResponse{}, fmt.Errorf("verify committed managed material: %w", err)
		}
	}
	for range 8 {
		if _, err := control.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
			return placementApplyResponse{}, authority.ErrFenced
		} else if !errors.Is(err, authority.ErrNotFound) {
			return placementApplyResponse{}, err
		}
		current, err := control.ReadPlacementIntent(ctx, intent.DatabaseID, intent.PartitionID)
		if err == nil {
			old, err := placement.DecodeCommittedIntent(current.Payload)
			if err != nil || old.DatabaseID != intent.DatabaseID || old.PartitionID != intent.PartitionID {
				return placementApplyResponse{}, errors.New("durable placement intent is corrupt")
			}
			if old.Generation != intent.Generation || !bytes.Equal(current.Payload, payload) {
				return placementApplyResponse{}, authority.ErrConflict
			}
			sequence, err := control.ConfirmActivePlacementIntent(ctx, envelope.Epoch, intent.DatabaseID, intent.PartitionID, payload)
			if err != nil {
				return placementApplyResponse{}, err
			}
			return placementApplyResponse{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID, Generation: intent.Generation, Sequence: sequence}, nil
		} else if !errors.Is(err, authority.ErrNotFound) {
			return placementApplyResponse{}, err
		}
		sequence, err := control.CommitPlacementIntent(ctx, envelope.Epoch, intent.DatabaseID, intent.PartitionID, placementOperationID(intent), 0, payload)
		if err == nil {
			return placementApplyResponse{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID, Generation: intent.Generation, Sequence: sequence}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return placementApplyResponse{}, err
		}
	}
	return placementApplyResponse{}, errors.New("placement intent contention")
}

func preparedMaterialAdmission(service managedmaterial.PreparationService) placementMaterialAdmission {
	return func(ctx context.Context, intent placement.Intent) error {
		receipt, err := service.Current(ctx, intent.DatabaseID, intent.PartitionID)
		if err != nil {
			return err
		}
		return managedmaterial.VerifyIntentAgainstReceipt(intent, receipt)
	}
}

func (r *Runtime) CommitPlacementIntent(
	ctx context.Context,
	expectedEpoch uint64,
	databaseID string,
	partitionID string,
	operationID string,
	expectedSequence uint64,
	payload []byte,
) (uint64, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return 0, err
	}
	if err := validateMutation(MutationPlacementIntent, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	release, err := r.beginWorkloadGate(ctx, WorkloadScope{DatabaseID: databaseID, PartitionID: partitionID})
	if err != nil {
		return 0, err
	}
	defer release()
	if err := r.requireNoTerminalIntent(ctx, databaseID, partitionID); err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, expectedEpoch, MutationPlacementIntent,
		subjectKey, operationID, expectedSequence, payload, func(check context.Context) error {
			return r.requireNoActiveBackup(check, databaseID, partitionID)
		})
}

// ConfirmActivePlacementIntent linearizes an identical admission with the
// terminal marker. Guard appends a global-sequence lease barrier, then the
// final leader-backed marker read rejects a marker committed by another leader
// before confirmation. A later marker overlaps this read-only admission.

func NewJetStreamStore(ctx context.Context, js jetstream.JetStream, cell string, replicas int, intents AdmittedIntentReader) (Store, error) {
	if !validToken(cell) || js == nil || intents == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("placement store requires cell, JetStream, admitted intent reader and valid replica count")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       stateBucketName,
		Description:  "Durable regional TerraBase placement member state",
		History:      2,
		MaxValueSize: maxStateBytes,
		MaxBytes:     128 << 20,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open placement member state: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil {
		return nil, fmt.Errorf("read placement member state status: %w", err)
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("placement state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	return &jetStreamStore{cell: cell, state: kv, intents: intents}, nil
}

func (store *jetStreamStore) ListMembers(ctx context.Context, databaseID, partitionID string) ([]VersionedMemberState, error) {
	if !validDatabaseKeyID(databaseID) || !entityid.Valid(partitionID) {
		return nil, fmt.Errorf("%w: database or partition id", ErrInvalidIntent)
	}
	// Every supported region has exactly two fixed seats in this schema.
	result := make([]VersionedMemberState, 0, len(regionsInOrder)*SeatsPerRegion)
	for _, region := range regionsInOrder {
		seats, err := RegionSeatIDs(region)
		if err != nil {
			return nil, err
		}
		for _, seat := range seats {
			member, err := store.ReadMember(ctx, databaseID, partitionID, seat)
			if errors.Is(err, ErrMemberNotFound) {
				continue
			}
			if err != nil {
				return nil, err
			}
			result = append(result, member)
		}
	}
	slices.SortFunc(result, func(a, b VersionedMemberState) int {
		return strings.Compare(a.State.MemberID, b.State.MemberID)
	})
	return result, nil
}

func (store *jetStreamStore) ReadMember(ctx context.Context, databaseID, partitionID, seatID string) (VersionedMemberState, error) {
	if !validDatabaseKeyID(databaseID) || !entityid.Valid(partitionID) ||
		!entityid.Valid(seatID) {
		return VersionedMemberState{}, fmt.Errorf("%w: database, partition, or seat id", ErrInvalidIntent)
	}
	key := memberStateKey(databaseID, partitionID, seatID)
	entry, err := store.state.Get(ctx, key)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return VersionedMemberState{}, ErrMemberNotFound
	}
	if err != nil {
		return VersionedMemberState{}, err
	}
	if entry.Operation() != jetstream.KeyValuePut {
		return VersionedMemberState{}, fmt.Errorf("%w: tombstone at %s", ErrStoreCorrupt, key)
	}
	return decodeMemberState(databaseID, partitionID, seatID, entry.Value(), entry.Revision())
}

func (store *jetStreamStore) CompareAndSwap(ctx context.Context, expected uint64, state MemberState) (uint64, error) {
	if err := state.Validate(); err != nil {
		return 0, err
	}
	data, err := json.Marshal(state)
	if err != nil {
		return 0, err
	}
	if len(data) > maxStateBytes {
		return 0, errors.New("placement member state exceeds size bound")
	}
	key := memberStateKey(state.DatabaseID, state.PartitionID, state.MemberID)
	var revision uint64
	if expected == 0 {
		revision, err = store.state.Create(ctx, key, data)
	} else {
		revision, err = store.state.Update(ctx, key, data, expected)
	}
	if err != nil {
		if errors.Is(err, jetstream.ErrKeyExists) || errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return 0, fmt.Errorf("%w: %v", ErrStoreConflict, err)
		}
		return 0, err
	}
	return revision, nil
}

case StagePreparedAttach:
	instance, exists := instances[state.InstanceID]
	if !exists {
		// An instance with an ATTACHING volume is withheld from
		// observation; a requested attach still runs against its
		// deadline.
		controller.holdStalledAttachRequest(seat.MemberID, state)
		return false, nil
	}
	if err := controller.validateObservedInstance(instance, state, seat); err != nil {
		return false, err
	}
	status, admitted := controller.admittedHost(intent, state, instance, statuses)
	if !admitted || status.Registration.Generation != state.HostGeneration {
		return false, nil
	}
	if !controller.runtimeArtifactReady(ctx, state, seat) {
		return false, nil
	}
	if err := controller.verifyHostImage(ctx, instance); err != nil {
		return false, err
	}
	if state.PreviousInstanceID != "" {
		return controller.reattachRetainedVolume(ctx, epoch, intent, seat, versioned)
	}
	var attachment *oci.Attachment
	for index := range instance.Attachments {
		if instance.Attachments[index].VolumeID == state.VolumeID {
			if instance.Attachments[index].InstanceID != state.InstanceID {
				return false, oci.ErrRetainedVolumeInUse
			}
			attachment = &instance.Attachments[index]
			break
		}
	}
	if attachment == nil {
		if state.AttachRequestedAt.IsZero() {
			// Record when the attach starts, durably, so its deadline
			// survives restarts and settle-wait failures.
			state.AttachRequestedAt = controller.currentTime().UTC()
			revision, err := controller.persist(ctx, epoch, versioned.Revision, state)
			if err != nil {
				return false, err
			}
			versioned.Revision = revision
		}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		attached, err := controller.fleet.AttachRetainedVolume(ctx, oci.VolumeAttachRequest{
			DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
			VolumeID: state.VolumeID, InstanceID: state.InstanceID,
			IdempotencyKey: memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach-volume"),
		})
		if err != nil {
			controller.holdStalledAttachRequest(seat.MemberID, state)
			return false, fmt.Errorf("attach retained member volume %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
		}
		attachment = &attached
	}
	state.AttachmentID = attachment.ID
	if attachment.State == "ATTACHED" {
		state.AttachRequestedAt = time.Time{}
		state.Stage = StageAwaitingRuntimeContract
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "runtime-hold")
	} else if attachment.State == "ATTACHING" {
		state.Stage = StageAwaitingAttach
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "attach-wait")
	} else {
		controller.hold(fmt.Sprintf("member %s retained volume attachment is %s; desired state remains withheld", seat.MemberID, attachment.State))
		return false, nil
	}

func (f *fleet) verifyRetainedVolumeHostImage(cloud CloudInstance) error {
	if !f.imageAllowed(cloud.ImageID) || cloud.ConsistentVolumeNamingEnabled == nil || !*cloud.ConsistentVolumeNamingEnabled {
		return fmt.Errorf("%w: instance %s does not report an allowed image and consistent volume naming", ErrImageNotQualified, cloud.ID)
	}
	return nil
}

func (f *fleet) AttachRetainedVolume(ctx context.Context, request VolumeAttachRequest) (Attachment, error) {
	if request.VolumeID == "" || request.InstanceID == "" || !validCreateKey(request.IdempotencyKey) {
		return Attachment{}, errors.New("retained volume attach request is incomplete")
	}
	if f.imageVerifier == nil {
		return Attachment{}, ErrImageQualificationUnavailable
	}
	epoch, err := f.currentEpoch()
	if err != nil {
		return Attachment{}, err
	}
	release, err := f.beginActiveWorkloadEffect(ctx, epoch, request.DatabaseID, request.PartitionID)
	if err != nil {
		return Attachment{}, err
	}
	defer release()
	instance, identity, err := f.ownedInstance(ctx, request.InstanceID)
	if err != nil {
		return Attachment{}, err
	}
	if err := f.verifyRetainedVolumeHostImage(instance); err != nil {
		return Attachment{}, err
	}
	// The image the host boots, not the launch image, must qualify now: a
	// retained volume attaches only to a host of a currently approved image.
	if err := f.verifyImage(ctx, instance.ImageID); err != nil {
		return Attachment{}, err
	}
	volume, err := f.ownedVolume(ctx, request.VolumeID)
	if err != nil {
		return Attachment{}, err
	}
	if err := f.verifyAttachScope(ctx, request.DatabaseID, request.PartitionID, request.InstanceID, volume); err != nil {
		return Attachment{}, err
	}

func newDeployTestProvider(config oci.RegionConfig, consistentNaming, inTransit bool) *deployTestProvider {
	return &deployTestProvider{config: config, consistentNaming: consistentNaming, inTransit: inTransit,
		boot: make(map[string]oci.CloudBootVolume), volumeRetries: make(map[string]string)}
}

func cloneInstance(instance oci.CloudInstance) oci.CloudInstance {
	instance.Metadata = maps.Clone(instance.Metadata)
	instance.FreeformTags = maps.Clone(instance.FreeformTags)
	return instance
}

func (p *deployTestProvider) ListInstances(_ context.Context, compartmentID string) ([]oci.CloudInstance, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if compartmentID != p.config.CompartmentID {
		return nil, oci.ErrForeignResource
	}
	instances := make([]oci.CloudInstance, 0, len(p.instances))
	for _, instance := range p.instances {
		instances = append(instances, cloneInstance(instance))
	}
	return instances, nil
}

func (p *deployTestProvider) GetInstance(_ context.Context, instanceID string) (oci.CloudInstance, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	for _, instance := range p.instances {
		if instance.ID == instanceID {
			return cloneInstance(instance), nil
		}
	}
	return oci.CloudInstance{}, errors.New("unknown fake OCI instance")
}

func (p *deployTestProvider) LaunchInstance(_ context.Context, request oci.LaunchRequest) (oci.CloudInstance, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	for index, launch := range p.launches {
		if launch.RetryToken == request.RetryToken {
			return cloneInstance(p.instances[index]), nil
		}
	}
	region, err := p.config.Region.OCIRegion()
	if err != nil {
		return oci.CloudInstance{}, err
	}
	number := len(p.instances) + 1
	instance := oci.CloudInstance{
		ID: fmt.Sprintf("ocid1.instance.oc1.%s.member%d", region, number), CompartmentID: p.config.CompartmentID,
		PrivateIP: request.PrivateIP, AvailabilityDomain: p.config.AvailabilityDomain, FaultDomain: request.FaultDomain,
		Shape: request.Shape, Ocpus: new(float32(request.WholeOCPUs)), MemoryInGBs: new(float32(request.MemoryInGBs)),
		LifecycleState: "RUNNING", ETag: fmt.Sprintf("instance-etag-%d", number), ImageID: request.ImageID,
		ConsistentVolumeNamingEnabled: new(p.consistentNaming),
		Metadata:                      map[string]string{hostboot.MetadataKey: request.BootDescriptor, "terrascale_host_node": request.Node},
		FreeformTags:                  maps.Clone(request.FreeformTags),
	}
	request.FreeformTags = maps.Clone(request.FreeformTags)
	p.launches = append(p.launches, request)
	p.instances = append(p.instances, instance)
	suffix, _ := strings.CutPrefix(instance.ID, "ocid1.instance.")
	p.boot[instance.ID] = oci.CloudBootVolume{ID: "ocid1.bootvolume." + suffix, CompartmentID: p.config.CompartmentID,
		AvailabilityDomain: p.config.AvailabilityDomain, ImageID: request.ImageID,
		SizeGB: int64(p.config.BootVolumeGB), VPUsPerGB: int64(p.config.BootVolumeVPUsPerGB),
		LifecycleState: "AVAILABLE", ETag: fmt.Sprintf("boot-etag-%d", number)}
	return cloneInstance(instance), nil
}

func (p *deployTestProvider) AttachVolume(_ context.Context, request oci.CloudVolumeAttachRequest) (oci.CloudAttachment, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	for _, attachment := range p.attachments {
		if attachment.VolumeID == request.VolumeID {
			return attachment, nil
		}
	}
	number := len(p.attachments) + 1
	attachment := oci.CloudAttachment{ID: fmt.Sprintf("ocid1.volumeattachment.oc1..member%d", number),
		VolumeID: request.VolumeID, InstanceID: request.InstanceID, LifecycleState: "ATTACHED",
		ETag: fmt.Sprintf("attachment-etag-%d", number), Device: request.Device,
		IsReadOnly: new(request.IsReadOnly), IsShareable: new(request.IsShareable),
		IsPvEncryptionInTransitEnabled: new(request.IsPvEncryptionInTransitEnabled && p.inTransit)}
	p.attachments = append(p.attachments, attachment)
	return attachment, nil
}

func (appNativeMaterialValidator) ValidateManagedMaterial(_ context.Context, input managedmaterial.NativeMaterialInput, pin string) error {
	if len(input.Certificate) == 0 || len(input.SignedV2S3Config) == 0 || input.ExpectedS3TargetDigest == "" || pin == "" {
		return errors.New("native material request is incomplete")
