}

func requestPlacementStatus(ctx context.Context, cfg Config, runtime *natscell.Runtime,
	database, partition string,
) (placementStatusReport, error) {
	policy, err := buildSignerPolicy(cfg)
	if err != nil {
		return placementStatusReport{}, statusRejected{err}
	}
	grant, exists := policy.grant(cfg.Operator.Actor)
	if !exists || !grant.CanPlaceTerraBase {
		return placementStatusReport{}, statusRejected{errors.New("operator is not authorized to read TerraBase placement status")}
	}
	codec, err := policy.withOperator(cfg.Operator)
	if err != nil {
		return placementStatusReport{}, statusRejected{err}
	}
	controllerKey, err := decodePublicKey(cfg.Operator.ControllerPublicKey)
	if err != nil {
		return placementStatusReport{}, statusRejected{fmt.Errorf("operator controller key pin: %w", err)}
	}
	epoch, err := authoritySnapshot(ctx, runtime, cfg.NATS.Cell)
	if err != nil {
		return placementStatusReport{}, err
	}
	var nonce [16]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return placementStatusReport{}, err
	}
	request := placementStatusRequest{DatabaseID: database, PartitionID: partition, Nonce: hex.EncodeToString(nonce[:])}
	payload, err := protocol.EncodeJSON(request)
	if err != nil {
		return placementStatusReport{}, err
	}
	scope := protocol.EnvelopeScope{Region: cfg.NATS.Cell, Kind: managedKindPlacementStatus, Actor: cfg.Operator.Actor,
		OperationID: entityid.Derive("status", request.Nonce), Generation: 1, Epoch: epoch}
	now := time.Now().UTC()
	envelope, err := protocol.SignEnvelope(payload, scope, now, now.Add(time.Minute), codec.PrivateKey)
	if err != nil {
		return placementStatusReport{}, err
	}
	wire, err := protocol.EncodeJSON(envelope)
	if err != nil {
		return placementStatusReport{}, err
	}
	requestCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	message, err := runtime.Conn().RequestWithContext(requestCtx, managedAdmissionSubject(cfg.NATS.Cell), wire)
	if err != nil {
		return placementStatusReport{}, fmt.Errorf("request TerraBase placement status: %w", err)
	}
	var signed protocol.Envelope
	if err := protocol.DecodeStrict(message.Data, &signed, maxPlacementStatusReplyBytes); err != nil {
		return placementStatusReport{}, statusRejected{err}
	}
	scope.Kind, scope.Actor = placementStatusReplyKind, "controller"
	if err := protocol.VerifyEnvelope(signed, scope, controllerKey, time.Now().UTC(),
		protocol.VerifyPolicy{MaxLifetime: time.Minute, ClockSkew: 30 * time.Second}); err != nil {
		return placementStatusReport{}, statusRejected{fmt.Errorf("unauthenticated placement status: %w", err)}
	}
	var report placementStatusReport
	if err := protocol.DecodeStrict(signed.Payload, &report, maxPlacementStatusReplyBytes); err != nil {
		return placementStatusReport{}, statusRejected{err}
	}
	if report.Cell != cfg.NATS.Cell || report.DatabaseID != database || report.PartitionID != partition ||
		report.Nonce != request.Nonce {
		return placementStatusReport{}, statusRejected{errors.New("placement status reply answers a different request")}
	}
	return report, nil
}

func (source placementStatusSource) report(ctx context.Context, request placementStatusRequest, epoch uint64) (placementStatusReport, error) {
	now := time.Now().UTC()
	report := placementStatusReport{Cell: source.cell, DatabaseID: request.DatabaseID, PartitionID: request.PartitionID,
		Nonce: request.Nonce, ObservedAt: now, AuthorityEpoch: epoch,
		Readiness: "unknown", ReadinessReason: "current native root task and member readiness source is unavailable"}
	intents, err := source.placements.ListIntents(ctx)
	if err != nil {
		return placementStatusReport{}, err
	}
	var intent *placement.Intent
	for index := range intents {
		if intents[index].DatabaseID == request.DatabaseID && intents[index].PartitionID == request.PartitionID {
			intent = &intents[index]
		}
	}
	if _, err := source.placements.ReadTerminalIntent(ctx, request.DatabaseID, request.PartitionID); err == nil {
		report.Terminal = true
	} else if !errors.Is(err, authority.ErrNotFound) {
		return placementStatusReport{}, err
	}
	members, err := source.placements.ListMembers(ctx, request.DatabaseID, request.PartitionID)
	if err != nil {
		return placementStatusReport{}, err
	}
	statuses, err := source.hosts.ListHosts(ctx)
	if err != nil {
		return placementStatusReport{}, err
	}
	byNode := make(map[string]host.HostStatus, len(statuses))
	for _, status := range statuses {
		byNode[status.Registration.Node] = status
	}
	byMember := make(map[string]placement.MemberState, len(members))
	for _, member := range members {
		byMember[member.State.MemberID] = member.State
	}
	var seats []string
	if intent != nil {
		report.Generation, report.PayloadSHA256 = intent.Generation, intent.PayloadDigest()
		for _, row := range intent.CanonicalRoster.Rows {
			seats = append(seats, row.SeatID)
		}
		entry, err := source.control.ReadPlacementIntent(ctx, request.DatabaseID, request.PartitionID)
		if err != nil {
			return placementStatusReport{}, err
		}
		report.Sequence = entry.Sequence
	}
	for _, member := range members {
		if !slices.Contains(seats, member.State.MemberID) {
			seats = append(seats, member.State.MemberID)
		}
	}
	for _, seat := range seats {
		entry := placementMemberStatus{SeatID: seat, Stage: "unprepared"}
		if intent != nil {
			for _, row := range intent.CanonicalRoster.Rows {
				if row.SeatID == seat {
					entry.MemberID, entry.FailureDomain = row.MemberID, row.FailureDomain
				}
			}
		}
		if state, exists := byMember[seat]; exists {
			manifest := state.EffectiveRuntimeManifest()
			entry.MemberID, entry.FailureDomain = state.CanonicalRosterRow.MemberID, state.FailureDomain
			entry.Stage, entry.HostAttempt = string(state.Stage), state.HostAttempt
			entry.InstanceID, entry.HostNode, entry.VolumeID = state.InstanceID, state.HostNode, state.VolumeID
			entry.AttachmentID, entry.AttachmentDevice = state.AttachmentID, state.AttachmentDevice
			entry.DesiredGeneration, entry.ArtifactDigest, entry.UpdatedAt = state.DesiredGeneration, manifest.ArtifactDigest, state.UpdatedAt
			if target := state.ManagedRuntimeTarget; target.OperationID != "" {
				entry.Update = &placementUpdateStatus{OperationID: target.OperationID, ArtifactDigest: target.ArtifactDigest,
					SourceDigest: target.SourceDigest, PreviousArtifactDigest: target.PreviousArtifactDigest,
					Phase: string(target.Phase), Outcome: target.Outcome}
			}
			if state.InstanceID != "" && state.AttachmentID != "" && state.DesiredGeneration != 0 {
				pins := placement.ManagedUpdateSeatFor(state, source.owner, source.fleetGeneration)
				entry.UpdatePins = &pins
			}
			if status, registered := byNode[state.HostNode]; registered && state.HostNode != "" {
				entry.Host = memberHostStatus(status, now)
			}
		}
		report.Members = append(report.Members, entry)
	}
	report.Holds = source.holds.recent(now)
	for index := range report.Holds {
		if !holdMentions(report.Holds[index].Reason, request, seats) {
			report.Holds[index].Reason = ""
		}
	}
	report.Holds = slices.DeleteFunc(report.Holds, func(record placementHoldRecord) bool { return record.Reason == "" })
	return report, nil
}

func startFakeRolloutController(t *testing.T, cell *deployTestCellServices, intent placement.Intent) *fakeRolloutController {
	t.Helper()
	entry, err := cell.control.ReadPlacementIntent(t.Context(), intent.DatabaseID, intent.PartitionID)
	if err != nil {
		t.Fatal(err)
	}
	if err := cell.status.Unsubscribe(); err != nil {
		t.Fatal(err)
	}
	fake := &fakeRolloutController{cell: cell, intent: intent, sequence: entry.Sequence}
	for _, row := range intent.CanonicalRoster.Rows {
		manifest, err := intent.RuntimeManifestForSeat(placement.Seat{MemberID: row.SeatID, Region: row.Region})
		if err != nil {
			t.Fatal(err)
		}
		digest, err := manifest.Digest()
		if err != nil {
			t.Fatal(err)
		}
		// Every seat has a live host report, as a real host publishes.
		fake.seats = append(fake.seats, &fakeRolloutSeat{serving: true, pid: 100, pins: placement.ManagedUpdateSeat{
			SeatID: row.SeatID, Region: row.Region, MemberID: row.MemberID, Incarnation: row.Incarnation,
			TLSLeafSHA256: row.TLSLeafSHA256, RuntimeManifestDigest: digest, HostNode: "host-" + strings.ToLower(row.SeatID),
			HostGeneration: 1, HostAttempt: 1, OCIInstanceID: "ocid1.instance.oc1..fake-" + row.SeatID,
			OCIOwner: deployTestOwner, OCIFleetGeneration: 1, CreateKey: entityid.Derive("test-create", row.SeatID),
			VolumeID: "ocid1.volume.oc1..fake-" + row.SeatID, AttachmentID: "ocid1.volumeattachment.oc1..fake-" + row.SeatID,
			AttachmentETag: "etag", AttachmentDevice: "/dev/oracleoci/oraclevdb", DesiredGeneration: 1,
			ArtifactDigest: manifest.ArtifactDigest}})
	}
	fake.serve(t)
	return fake
}

func (fake *fakeRolloutController) serve(t *testing.T) {
	t.Helper()
	ctx := t.Context()
	conn := fake.cell.broker.Conn()
	status, err := serveManagedAdmissionKind(ctx, conn, deployTestCell, managedKindPlacementStatus,
		func(_ context.Context, message *nats.Msg) {
			if wire, err := fake.status(message.Data); err == nil {
				_ = message.Respond(wire)
			}
		})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = status.Unsubscribe() })
	prepare, err := conn.Subscribe(managedUpdatePrepareSubject(deployTestCell), func(message *nats.Msg) {
		response, err := fake.prepare(message.Data)
		if err != nil {
			fake.mu.Lock()
			fake.rejected = append(fake.rejected, err)
			fake.mu.Unlock()
			response = managedUpdatePrepareResponse{Error: err.Error()}
		}
		if wire, err := json.Marshal(response); err == nil {
			_ = message.Respond(wire)
		}
	})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = prepare.Unsubscribe() })
	if err := conn.Flush(); err != nil {
		t.Fatal(err)
	}
}

func (fake *fakeRolloutController) prepare(wire []byte) (managedUpdatePrepareResponse, error) {
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(wire, &envelope, managedUpdateRequestMaxBytes); err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	var intent placement.ManagedUpdateIntent
	if err := protocol.DecodeStrict(envelope.Payload, &intent, protocol.MaxPayloadBytes); err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	if err := intent.Validate(); err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	grant, exists := fake.cell.policy.grant(envelope.Actor)
	trusted, known := fake.cell.policy.trusted(envelope.KeyID)
	if !exists || !grant.CanUpdateTerraBaseRuntime || !known || trusted.Actor != envelope.Actor ||
		protocol.VerifyEnvelope(envelope, protocol.EnvelopeScope{Region: deployTestCell,
			Kind: placement.ManagedUpdateEnvelopeKind, Actor: trusted.Actor, OperationID: intent.OperationID,
			Generation: intent.CanaryDesiredGeneration, Epoch: intent.AuthorityEpoch}, trusted.PublicKey, time.Now().UTC(),
			protocol.VerifyPolicy{MaxLifetime: 5 * time.Minute, ClockSkew: 30 * time.Second}) != nil {
		return managedUpdatePrepareResponse{}, errors.New("managed update signature or grant rejected")
	}
	if err := verifyManagedCompatibility(intent, envelope, fake.cell.policy); err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	payload, err := protocol.EncodeJSON(fake.intent)
	if err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	decoded, err := placement.DecodeCommittedIntent(payload)
	if err != nil || intent.PlacementPayloadDigest != decoded.PayloadDigest() || intent.PlacementSequence != fake.sequence ||
		intent.Environment != "canary" || intent.DurabilityProfile.Region != oci.RegionGRU {
		return managedUpdatePrepareResponse{}, errors.New("managed update does not pin the admitted placement")
	}
	fake.mu.Lock()
	defer fake.mu.Unlock()
	var canary *fakeRolloutSeat
	for index, seat := range fake.seats {
		if !slices.ContainsFunc(intent.Seats, func(pin placement.ManagedUpdateSeat) bool { return pin == seat.pins }) {
			return managedUpdatePrepareResponse{}, errors.New("managed update seat pins differ from the durable seat")
		}
		if seat.pins.SeatID == intent.CanarySeatID {
			canary = fake.seats[index]
		} else if !seat.serving {
			return managedUpdatePrepareResponse{}, errors.New("peer is not serving")
		}
	}
	rollback := canary != nil && canary.update != nil && canary.update.Phase == updateHeldPhase &&
		intent.CandidateArtifactDigest == canary.update.PreviousArtifactDigest
	if canary == nil || canary.pins.ArtifactDigest != intent.OldArtifactDigest || !canary.serving && !rollback {
		return managedUpdatePrepareResponse{}, errors.New("canary is not at its signed serving predecessor")
	}
	fake.prepares = append(fake.prepares, intent)
	canary.update = &placementUpdateStatus{OperationID: intent.OperationID, ArtifactDigest: intent.CandidateArtifactDigest,
		SourceDigest: intent.CandidateSourceDigest, PreviousArtifactDigest: intent.OldArtifactDigest,
		Phase: updatePreparedPhase}
	canary.pins.ArtifactDigest, canary.pins.DesiredGeneration = intent.CandidateArtifactDigest, intent.CanaryDesiredGeneration
	canary.serving = false
	return managedUpdatePrepareResponse{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID,
		OperationID: intent.OperationID, Phase: string(authority.ManagedUpdatePrepared), Sequence: uint64(100 + len(fake.prepares))}, nil
}

func (fake *fakeRolloutController) status(wire []byte) ([]byte, error) {
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(wire, &envelope, maxPlacementStatusRequestBytes+4096); err != nil {
		return nil, err
	}
	var request placementStatusRequest
	if err := protocol.DecodeStrict(envelope.Payload, &request, maxPlacementStatusRequestBytes); err != nil {
		return nil, err
	}
	payload, err := protocol.EncodeJSON(fake.intent)
	if err != nil {
		return nil, err
	}
	decoded, err := placement.DecodeCommittedIntent(payload)
	if err != nil {
		return nil, err
	}
	fake.mu.Lock()
	report := placementStatusReport{Cell: deployTestCell, DatabaseID: request.DatabaseID, PartitionID: request.PartitionID,
		Nonce: request.Nonce, ObservedAt: time.Now().UTC(), AuthorityEpoch: envelope.Epoch,
		Generation: fake.intent.Generation, PayloadSHA256: decoded.PayloadDigest(), Sequence: fake.sequence, Serving: true}
	for _, seat := range fake.seats {
		if seat.update != nil && seat.update.Phase == updatePreparedPhase {
			failing := seat.update.ArtifactDigest == fake.failing &&
				(fake.failingSeat == "" || fake.failingSeat == seat.pins.SeatID) ||
				seat.update.ArtifactDigest == fake.failingToo
			if failing {
				seat.update.Phase, seat.update.Outcome = updateHeldPhase, "candidate-proof-timeout"
			} else {
				seat.update.Phase, seat.update.Outcome = string(placement.ManagedUpdateSeatCanaryServing), "canary-serving"
				seat.serving = true
			}
		}
		if seat.update != nil && seat.update.ArtifactDigest == fake.restarting &&
			seat.update.Phase == string(placement.ManagedUpdateSeatCanaryServing) {
			seat.pid++
		}
		stage := string(placement.StageServing)
		if !seat.serving {
			stage = string(placement.StageAwaitingHealthy)
		}
		pins := seat.pins
		member := placementMemberStatus{SeatID: pins.SeatID, MemberID: pins.MemberID, Stage: stage,
			ArtifactDigest: pins.ArtifactDigest, DesiredGeneration: pins.DesiredGeneration, UpdatePins: &pins}
		if seat.update != nil {
			update := *seat.update
			member.Update = &update
		}
		if seat.pid != 0 {
			member.Host = &placementHostStatus{ProcessPID: seat.pid, SessionCurrent: true, ReportState: "running",
				ServingProof: seat.serving}
		}
		report.Serving = report.Serving && seat.serving
		report.Members = append(report.Members, member)
	}
	fake.mu.Unlock()
	reportWire, err := protocol.EncodeJSON(report)
	if err != nil {
		return nil, err
	}
	now := time.Now().UTC()
	signed, err := protocol.SignEnvelope(reportWire, protocol.EnvelopeScope{Region: deployTestCell,
		Kind: placementStatusReplyKind, Actor: "controller", OperationID: entityid.Derive("status", request.Nonce),
		Generation: 1, Epoch: envelope.Epoch}, now, now.Add(time.Minute), fake.cell.controllerKey)
	if err != nil {
		return nil, err
	}
	return protocol.EncodeJSON(signed)
}

func operatorTerraBaseUpdate(ctx context.Context, cfg Config, runtime *natscell.Runtime, statePath string,
	files terrabaseReleaseFiles, compatibility terrabaseCompatibilitySigner, options terrabaseUpdateOptions, output io.Writer,
) error {
	state, err := openDeployState(statePath)
	if err != nil {
		return err
	}
	var intent placement.Intent
	var initial delivery.ArtifactRecord
	for name, value := range map[string]any{deployIntentFile: &intent, deployArtifactFile: &initial} {
		exists, err := state.readJSON(name, value)
		if err != nil {
			return err
		}
		if !exists {
			return fmt.Errorf("deployment state lacks %s; deploy before updating", name)
		}
	}
	if options.SeatWait <= 0 {
		options.SeatWait = defaultUpdateSeatWait
	}
	if options.Soak < 0 {
		return errors.New("soak must not be negative")
	}
	if options.poll <= 0 {
		options.poll = updateOutcomePoll
	}
	compatibilityKey, err := readPrivateKey(compatibility.KeyFile)
	if err != nil {
		return fmt.Errorf("compatibility signer key: %w", err)
	}
	defer clear(compatibilityKey)
	release, err := loadTerraBaseRelease(files)
	if err != nil {
		return err
	}
	record, err := pushArtifact(ctx, cfg, runtime, release.Binary, delivery.ArtifactClaimRequest{
		Source: release.Source, Cell: cfg.NATS.Cell, Role: initial.Role, Environment: initial.Environment})
	if err != nil {
		return classifyControllerError(fmt.Errorf("push TerraBase artifact: %w", err))
	}
	if record.Digest != release.Digest || record.Source != release.Source {
		return errors.New("controller admitted different TerraBase artifact bytes or source")
	}
	if _, err := state.ensureJSON(filepath.Join(deployReleaseDirectory, record.Digest+".json"), record); err != nil {
		return err
	}
	if err := retainReleaseCompatibility(state, release); err != nil {
		return err
	}
	report := func(step, status, detail string) error {
		return printJSON(output, terrabaseDeployStep{Step: step, Status: status, Detail: detail})
	}
	if err := report("artifact", "admitted", record.Digest); err != nil {
		return err
	}
	rollout := &terrabaseRollout{cfg: cfg, runtime: runtime, state: state, intent: intent, initial: initial,
		compatibility: compatibility, compatibilityKey: compatibilityKey, options: options, report: report,
		soaked: map[string]bool{}}
	return rollout.run(ctx, record)
}

type terrabaseRollout struct {
	cfg              Config
	runtime          *natscell.Runtime
	state            deployState
	intent           placement.Intent
	initial          delivery.ArtifactRecord

		}
		status, err := rollout.status(ctx)
		if err != nil {
