// canary keeps Stage serving even after it loses its serving proof (the
// controller only records a hold), so serving also requires the host's
// current report to carry a serving proof and no error. Without a current
// host session or report the sample is a gap: unknown, not failed.
func soakSample(member placementMemberStatus, now time.Time) staged.SoakSample {

func (rollout *terrabaseRollout) compatibilityVerdict(old, candidate string) (staged.CompatibilityVerdict, error) {
	oldDeclaration, oldKnown, err := releaseCompatibility(rollout.state, old)
	if err != nil {
		return staged.CompatibilityVerdict{}, err
	}
	candidateDeclaration, candidateKnown, err := releaseCompatibility(rollout.state, candidate)
	if err != nil {
		return staged.CompatibilityVerdict{}, err
	}
	if oldKnown && candidateKnown {
		verdict, err := staged.RequireCompatible(oldDeclaration, candidateDeclaration)
		if err != nil {
			return verdict, fmt.Errorf("%s -> %s: %w", old, candidate, err)
		}
		return verdict, nil
	}
	// Name every release that lacks a declaration, so the operator publishes
	// all of them at once.
	var missing []string
	if !oldKnown {
		missing = append(missing, old)
	}
	if !candidateKnown {
		missing = append(missing, candidate)
	}
	if !rollout.options.AssumeCompatible {
		return staged.CompatibilityVerdict{}, staged.Terminal(fmt.Errorf(
			"%w: %s; publish compatibility in each qualification.json or pass --assume-compatibility to certify it unverified",
			staged.ErrNoCompatibilityData, strings.Join(missing, ", ")))
	}
	if err := rollout.report("compatibility", "assumed", old+" -> "+candidate); err != nil {
		return staged.CompatibilityVerdict{}, err
	}
	return staged.CompatibilityVerdict{MixedVersionReplication: true, ClientData: true,
		PersistentFormatRead: true, PersistentFormatWrite: true}, nil
}

func (rollout *terrabaseRollout) await(ctx context.Context, seatID, operation string) (string, error) {
	deadline := time.Now().Add(rollout.options.SeatWait)
	for {
		status, err := rollout.status(ctx)
		if err != nil {
			return "", err
		}
		index := slices.IndexFunc(status.Members, func(member placementMemberStatus) bool { return member.SeatID == seatID })
		if index < 0 {
			return "", staged.Terminal(fmt.Errorf("seat %s disappeared from placement status", seatID))
		}
		member := status.Members[index]
		if member.Update != nil && member.Update.OperationID == operation && member.Update.Phase != updatePreparedPhase {
			return member.Update.Phase, rollout.report("seat "+seatID, member.Update.Phase, member.Update.ArtifactDigest)
		}
		if !time.Now().Before(deadline) {
			return "", staged.Transient(fmt.Errorf("seat %s operation %s did not reach an outcome within %s",
				seatID, operation, rollout.options.SeatWait))
		}
		timer := time.NewTimer(min(rollout.options.poll, time.Until(deadline)))
		select {
		case <-ctx.Done():
			timer.Stop()
			return "", ctx.Err()
		case <-timer.C:
		}
	}
}

// status reads signed placement status. Transport, timeout and authority
// lease failures are transient; authorization, key and reply verification
// failures are terminal, because no retry can fix them.
func (rollout *terrabaseRollout) status(ctx context.Context) (placementStatusReport, error) {
	status, err := requestPlacementStatus(ctx, rollout.cfg, rollout.runtime, rollout.intent.DatabaseID, rollout.intent.PartitionID)
	if err != nil {
		return placementStatusReport{}, classifyStatusError(err)
	}
	return status, nil
}

// recordKnownBad durably marks digest known bad before any rollback acts on
// it. The first record wins; later failures of the same digest keep it.
func (rollout *terrabaseRollout) recordKnownBad(status placementStatusReport, digest, reason string) error {
	record := staged.KnownBad{Digest: digest, Reason: reason, RecordedAt: time.Now().UTC()}
	for _, member := range status.Members {
		if member.Update != nil && member.Update.ArtifactDigest == digest {
			record.SeatID, record.OperationID = member.SeatID, member.Update.OperationID
			break
		}
	}
	if err := record.Validate(); err != nil {
		return err
	}
	if _, err := rollout.state.readOrCreateJSON(filepath.Join(deployKnownBadDirectory, digest+".json"), record); err != nil {
		return err
	}
	return rollout.report("known-bad", "recorded", digest)
}

// knownBad loads every retained known-bad record of the deployment.
func (state deployState) knownBad() (staged.KnownBadSet, error) {
	entries, err := os.ReadDir(filepath.Join(state.directory, deployKnownBadDirectory))
	if err != nil {
		return nil, err
	}
	set := staged.KnownBadSet{}
	for _, entry := range entries {
		match := knownBadFilePattern.FindStringSubmatch(entry.Name())
		if match == nil {
			continue
		}
		var record staged.KnownBad
		if _, err := state.readJSON(filepath.Join(deployKnownBadDirectory, entry.Name()), &record); err != nil {
			return nil, err
		}
		if err := record.Validate(); err != nil || record.Digest != match[1] {
			return nil, fmt.Errorf("retained known-bad record %s is invalid", entry.Name())
		}
		set[record.Digest] = record
	}
	return set, nil
}

func requestManagedUpdatePrepare(ctx context.Context, cfg Config, runtime *natscell.Runtime,
	intent placement.ManagedUpdateIntent,
) (managedUpdatePrepareResponse, error) {
	if err := intent.Validate(); err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	if intent.Cell != cfg.NATS.Cell {
		return managedUpdatePrepareResponse{}, errors.New("managed update intent does not select this regional cell")
	}
	policy, err := buildSignerPolicy(cfg)
	if err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	grant, exists := policy.grant(cfg.Operator.Actor)
	if !exists || !grant.CanPlaceTerraBase || !grant.CanUpdateTerraBaseRuntime ||
		!slices.Contains(grant.Roles, intent.Role) || !slices.Contains(grant.Environments, intent.Environment) {
		return managedUpdatePrepareResponse{}, errors.New("operator lacks current TerraBase managed runtime update scope")
	}
	codec, err := policy.withOperator(cfg.Operator)
	if err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	epoch, err := authoritySnapshot(ctx, runtime, cfg.NATS.Cell)
	if err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	if intent.AuthorityEpoch != epoch {
		return managedUpdatePrepareResponse{}, authority.ErrFenced
	}
	canonicalIntent, err := protocol.EncodeJSON(intent)
	if err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	now := time.Now().UTC()
	envelope, err := protocol.SignEnvelope(canonicalIntent, protocol.EnvelopeScope{
		Region: cfg.NATS.Cell, Kind: placement.ManagedUpdateEnvelopeKind, Actor: cfg.Operator.Actor,
		OperationID: intent.OperationID, Generation: intent.CanaryDesiredGeneration, Epoch: epoch,
	}, now, now.Add(time.Minute), codec.PrivateKey)
	if err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	wire, err := protocol.EncodeJSON(envelope)
	if err != nil {
		return managedUpdatePrepareResponse{}, err
	}
	for attempt := range 3 {
		requestCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
		message, requestErr := runtime.Conn().RequestWithContext(requestCtx, managedUpdatePrepareSubject(cfg.NATS.Cell), wire)
		cancel()
		if requestErr == nil {
			var response managedUpdatePrepareResponse
			if err := protocol.DecodeStrict(message.Data, &response, 16<<10); err != nil {
				return managedUpdatePrepareResponse{}, fmt.Errorf("decode managed update Prepare reply: %w", err)
			}
			if response.Error != "" {
				return managedUpdatePrepareResponse{}, errors.New(response.Error)
			}
			if response.DatabaseID != intent.DatabaseID || response.PartitionID != intent.PartitionID ||
				response.OperationID != intent.OperationID || response.Phase != string(authority.ManagedUpdatePrepared) || response.Sequence == 0 {
				return managedUpdatePrepareResponse{}, errors.New("controller returned a different managed update Prepare receipt")
			}
			return response, nil
		}
		if (!errors.Is(requestErr, nats.ErrTimeout) && !errors.Is(requestErr, context.DeadlineExceeded)) || attempt == 2 {
			return managedUpdatePrepareResponse{}, fmt.Errorf("request managed update Prepare: %w", requestErr)
		}
	}
	return managedUpdatePrepareResponse{}, errors.New("managed update Prepare request exhausted")
}

func serveManagedAdmissionKind(ctx context.Context, conn *nats.Conn, cell, kind string,
	handle func(context.Context, *nats.Msg),
) (*nats.Subscription, error) {
	return conn.Subscribe(managedAdmissionSubject(cell), func(message *nats.Msg) {
		if message.Reply == "" || len(message.Data) == 0 || len(message.Data) > maxManagedAdmissionWireBytes ||
			managedAdmissionKind(message.Data) != kind {
			return
		}
		handle(ctx, message)
	})
}

func managedAdmissionKind(wire []byte) string {
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(wire, &envelope, maxManagedAdmissionWireBytes); err != nil {
		return ""
	}
	return envelope.Kind
}

func Qualification(t testing.TB, envs ...string) []string {
	t.Helper()
	if len(envs) == 0 {
		t.Fatal("tier.Qualification needs the environment variables that supply its fixture")
	}
	values := make([]string, len(envs))
	var missing []string
	for i, name := range envs {
		values[i] = os.Getenv(name)
		if values[i] == "" {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		Unavailable(t, "qualification fixture not supplied: set %s", strings.Join(missing, ", "))
	}
	return values
}

// Unavailable reports that a T2 fixture is missing for a reason the caller
// determined itself, such as an opt-in that needs one of several variables.
// It skips the test, or fails it in a qualification run.
func Unavailable(t testing.TB, format string, args ...any) {
	t.Helper()
	if Qualifying() {
		t.Fatalf(Env+"="+QualificationTier+": "+format, args...)
	}
	t.Skipf(format, args...)
}

func requireFiniteMemoryCgroup(t *testing.T) {
	t.Helper()
	membership, err := os.ReadFile("/proc/self/cgroup")
	if err == nil {
		for line := range strings.Lines(string(membership)) {
			if group, found := strings.CutPrefix(strings.TrimSpace(line), "0::"); found {
				limit, err := os.ReadFile(filepath.Join("/sys/fs/cgroup", group, "memory.max"))
				if err == nil && strings.TrimSpace(string(limit)) != "max" {
					return
				}
			}
		}
	}
	t.Fatal("tb-server needs a finite cgroup memory.max; run under systemd-run --user --scope -p MemoryMax=10G")
}

// runInMemberNamespace re-executes this test as the root of a fresh user and
// network namespace, mapped to the invoking user and group.
func runInMemberNamespace(t *testing.T) {
	command := exec.CommandContext(t.Context(), os.Args[0], "-test.run=^"+t.Name()+"$", "-test.count=1", "-test.v")
	command.Env = append(os.Environ(), walkthroughNamespaceEnv+"=1")
	command.SysProcAttr = &syscall.SysProcAttr{
		Cloneflags:  syscall.CLONE_NEWUSER | syscall.CLONE_NEWNET,
		UidMappings: []syscall.SysProcIDMap{{ContainerID: 0, HostID: os.Getuid(), Size: 1}},
		GidMappings: []syscall.SysProcIDMap{{ContainerID: 0, HostID: os.Getgid(), Size: 1}},
	}
	output, err := command.CombinedOutput()
	t.Logf("namespaced run:\n%s", output)
	if err != nil {
		t.Fatalf("namespaced walkthrough run failed: %v", err)
	}
}

func startWalkthroughMember(t *testing.T, server string, spec managedmaterial.InitialSpec,
	bundle managedmaterial.InitialBundle, index int,
) walkthroughMemberProcess {
	t.Helper()
	member, peer := spec.Members[index], spec.Members[1-index]
	material := member.MaterialDirectory
	volume := filepath.Join(filepath.Dir(material), "volume")
	for _, directory := range []string{material, filepath.Join(volume, "data"), filepath.Join(volume, "replication")} {
		if err := os.MkdirAll(directory, 0o700); err != nil {
			t.Fatal(err)
		}
	}
	for name, file := range bundle.Members[index].Files {
		if err := os.WriteFile(filepath.Join(material, name), file.Contents, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	process := walkthroughMemberProcess{seat: member.SeatID, adminPort: listener.Addr().(*net.TCPAddr).Port,
		log: filepath.Join(filepath.Dir(material), "tb-server.log"), exited: make(chan struct{})}
	_ = listener.Close()
	log, err := os.Create(process.log)
	if err != nil {
		t.Fatal(err)
	}
	defer log.Close()
	replication := func(ip string) string { return net.JoinHostPort(ip, strconv.Itoa(int(member.ReplicationPort))) }
	process.command = exec.Command(server,
		"--data-dir", filepath.Join(volume, "data"),
		"--memory-limit-bytes", strconv.FormatUint(4<<30, 10),
		"--memory-headroom-bytes", strconv.FormatUint(1<<30, 10),
		"--port", strconv.Itoa(process.adminPort),
		"--replication-listen-addr", replication(member.ReplicationIP),
		"--replication-data-dir", filepath.Join(volume, "replication", "shard"),
		"--authority-certificate", filepath.Join(material, "authority.tbca"),
		"--trusted-public-key", filepath.Join(material, "trusted-public-key"),
		"--replication-server-certificate", filepath.Join(material, "server.crt"),
		"--replication-server-private-key", filepath.Join(material, "server.key"),
		"--replication-client-ca-roots", filepath.Join(material, "client-ca.pem"),
		"--replication-peer-member-id", peer.MemberID,
		"--replication-peer-addr", replication(peer.ReplicationIP),
		"--replication-server-ca-roots", filepath.Join(material, "server-ca.pem"),
		"--cluster-id", spec.Scope.ClusterID,
		"--tenant-id", spec.Scope.TenantID,
		"--database-id", spec.Scope.DatabaseID,
		"--shard-id", strconv.FormatUint(spec.Scope.ShardID, 10),
		"--member-id", member.MemberID,
		"--member-incarnation", member.Incarnation,
		"--client-config", filepath.Join(material, "client-config.json"),
		"--client-allow-nonloopback")
	process.command.Stdout, process.command.Stderr = log, log
	if err := process.command.Start(); err != nil {
		t.Fatal(err)
	}
	go func() {
		_ = process.command.Wait()
		close(process.exited)
	}()
	t.Cleanup(func() {
		_ = process.command.Process.Signal(syscall.SIGTERM)
		select {
		case <-process.exited:
		case <-time.After(30 * time.Second):
			_ = process.command.Process.Kill()
			<-process.exited
		}
	})
	return process
}

// awaitReady polls the member's loopback administrative readiness endpoint.
func (process walkthroughMemberProcess) awaitReady(t *testing.T) {
	t.Helper()
	ready := fmt.Sprintf("http://127.0.0.1:%d/readyz", process.adminPort)
	for deadline := time.Now().Add(60 * time.Second); ; {
		if response, err := http.Get(ready); err == nil {
			_ = response.Body.Close()
			if response.StatusCode == http.StatusOK {
				return
			}
		}
		select {
		case <-process.exited:
			contents, _ := os.ReadFile(process.log)
			t.Fatalf("member %s exited before readiness: %s\n%s", process.seat, process.command.ProcessState, contents)
		case <-time.After(100 * time.Millisecond):
		}
		if time.Now().After(deadline) {
			contents, _ := os.ReadFile(process.log)
			t.Fatalf("member %s was not ready within 60s\n%s", process.seat, contents)
		}
	}
}

func runTerraBaseWalkthrough(ctx context.Context, args []string, output io.Writer) error {
	flags := flag.NewFlagSet("operator terrabase-walkthrough", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	statePath := flags.String("state", "", "terrabase-deploy state directory")
	var forwards walkthroughForwards
	flags.Var(&forwards, "forward", "MEMBER_IP:PORT=LOCAL_IP:PORT Bastion forward (repeatable)")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *statePath == "" || flags.NArg() != 0 {
		return errors.New("terrabase-walkthrough requires --state DIR")
	}
	state, err := openDeployState(*statePath)
	if err != nil {
		return err
	}
	// A profile written by an earlier orchestrator has other members, so read
	// its version before the strict decode below rejects them.
	if data, err := state.readFile(deployClientFile); err == nil {
		var probe struct {
			Version int `json:"version"`
		}
		if json.Unmarshal(data, &probe) == nil && probe.Version != terrabaseClientProfileVersion {
			return fmt.Errorf("client profile version %d is unsupported; this walkthrough reads version %d: "+
				"walk through this state with the orchestrator revision that deployed it, or redeploy with a new "+
				"--state and partition", probe.Version, terrabaseClientProfileVersion)
		}
	}
	var credentials managedmaterial.CustomerMaterial
	var profile terrabaseClientProfile
	for name, value := range map[string]any{deployCredentialsFile: &credentials, deployClientFile: &profile} {
		exists, err := state.readJSON(name, value)
		if err != nil {
			return err
		}
		if !exists {
			return fmt.Errorf("deployment state lacks %s; run terrabase-deploy first", name)
		}
	}
	if len(profile.Members) != 2 || len(profile.Collections) == 0 || len(profile.Collections[0].UTF8Fields) == 0 {
		return errors.New("client profile needs two members and a collection with a UTF-8 field")
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM([]byte(credentials.HTTPSCAPEM)) {
		return errors.New("deployment HTTPS CA is invalid")
	}
	client := walkthroughClient{token: credentials.Token, profile: profile, forwards: forwards, roots: roots,
		output: output}
	return client.run(ctx)
}

type walkthroughClient struct {
	token    string
	profile  terrabaseClientProfile
	forwards walkthroughForwards
	roots    *x509.CertPool
	output   io.Writer
	failed   int
}

func (client *walkthroughClient) run(ctx context.Context) error {
	a, b := client.profile.Members[0], client.profile.Members[1]
	collection := client.profile.Collections[0]
	scope := fmt.Sprintf("/v1/tenants/%s/databases/%s/shards/%d", client.profile.TenantID,
		client.profile.DatabaseID, client.profile.ShardID)
	document := entityid.New()
	point := scope + "/collections/" + collection.CollectionID + "/documents/" + document
	for _, member := range client.profile.Members {
		status, _, err := client.request(ctx, member, http.MethodGet, "/openapi.json", nil, "")
		client.expect("openapi", member, err == nil && status == http.StatusOK, status, err)
	}
	status, _, err := client.request(ctx, a, http.MethodGet, point, nil, "-")
	client.expect("missing-credential-rejected", a, err == nil && status == http.StatusUnauthorized, status, err)
	status, _, err = client.request(ctx, a, http.MethodGet, point, nil, "tbk1.AAAAAAAAAAAAAAAAAAAAAA.AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA")
	client.expect("invalid-credential-rejected", a, err == nil && status == http.StatusUnauthorized, status, err)
	foreign := fmt.Sprintf("/v1/tenants/%s/databases/%s/shards/%d/collections/%s/documents/%s", entityid.New(),
		client.profile.DatabaseID, client.profile.ShardID, collection.CollectionID, document)
	status, _, err = client.request(ctx, a, http.MethodGet, foreign, nil, "")
	client.expect("wrong-tenant-rejected", a, err == nil && status == http.StatusForbidden, status, err)
	if client.failed != 0 {
		return fmt.Errorf("%d walkthrough checks failed before any write", client.failed)
	}
	absent, err := client.read(ctx, b, point)
	client.expect("absent-before-write", b, err == nil && absent.State == "absent", 0, err)
	create := client.transaction(collection, document, jsontext.Value("[]"), "created by walkthrough")
	status, first, err := client.request(ctx, a, http.MethodPost, scope+"/transactions", create, "")
	client.expect("create", a, err == nil && status == http.StatusOK && receiptSequence(first) != "", status, err)
	status, retry, err := client.request(ctx, a, http.MethodPost, scope+"/transactions", create, "")
	client.expect("exact-retry-same-receipt", a, err == nil && status == http.StatusOK &&
		receiptSequence(retry) == receiptSequence(first), status, err)
	created, err := client.await(ctx, b, point, collection, "created by walkthrough")
	client.expect("replicated-read", b, err == nil, 0, err)
	if err != nil {
		return fmt.Errorf("%d walkthrough checks failed", client.failed)
	}
	update := client.transaction(collection, document, created.Context, "updated by walkthrough")
	status, _, err = client.request(ctx, b, http.MethodPost, scope+"/transactions", update, "")
	client.expect("update", b, err == nil && status == http.StatusOK, status, err)
	updated, err := client.await(ctx, a, point, collection, "updated by walkthrough")
	client.expect("replicated-update", a, err == nil, 0, err)
	if err == nil {
		tombstone := client.transaction(collection, document, updated.Context, "")
		status, _, err = client.request(ctx, a, http.MethodPost, scope+"/transactions", tombstone, "")
		client.expect("delete", a, err == nil && status == http.StatusOK, status, err)
		_, err = client.await(ctx, b, point, collection, "")
		client.expect("replicated-delete", b, err == nil, 0, err)
	}
	if client.failed != 0 {
		return fmt.Errorf("%d walkthrough checks failed", client.failed)
	}
	return printJSON(client.output, walkthroughCheck{Check: "walkthrough", Result: "passed", Detail: document})
}

func (client *walkthroughClient) expect(check string, member terrabaseClientMember, ok bool, status int, err error) {
	result := walkthroughCheck{Check: check, Member: member.SeatID, Result: "passed"}
	if !ok {
		client.failed++
		result.Result = "failed"
		switch {
		case err != nil:
			result.Detail = err.Error()
		case status != 0:
			result.Detail = "HTTP " + strconv.Itoa(status)
		}
	}
	_ = printJSON(client.output, result)
}

type walkthroughTransaction struct {
	Version       int                      `json:"version"`
	TransactionID walkthroughTransactionID `json:"transaction_id"`
	Writes        []walkthroughWrite       `json:"writes"`
}

func (client *walkthroughClient) request(ctx context.Context, member terrabaseClientMember, method, path string,
	body []byte, token string,
) (int, []byte, error) {
	target, err := url.Parse(member.URL)
	if err != nil || target.Scheme != "https" {
		return 0, nil, errors.New("member URL must be HTTPS")
	}
	dial := target.Host
	if local, forwarded := client.forwards[target.Host]; forwarded {
		dial = local
	}
	transport := &http.Transport{
		TLSClientConfig: &tls.Config{MinVersion: tls.VersionTLS12, RootCAs: client.roots, ServerName: target.Hostname()},
		DialContext: func(ctx context.Context, network, _ string) (net.Conn, error) {
			return (&net.Dialer{Timeout: 10 * time.Second}).DialContext(ctx, network, dial)
		},
		ForceAttemptHTTP2: false,
	}
	defer transport.CloseIdleConnections()
	requestCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(requestCtx, method, member.URL+path, bytes.NewReader(body))
	if err != nil {
		return 0, nil, err
	}
	switch token {
	case "":
		request.Header.Set("Authorization", "Bearer "+client.token)
	case "-":
	default:
		request.Header.Set("Authorization", "Bearer "+token)
	}
	if body != nil {
		request.Header.Set("Content-Type", "application/json")
	}
	response, err := (&http.Client{Transport: transport}).Do(request)
	if err != nil {
		return 0, nil, err
	}
	defer response.Body.Close()
	data, err := io.ReadAll(io.LimitReader(response.Body, maxWalkthroughResponse+1))
	if err != nil || len(data) > maxWalkthroughResponse {
		return response.StatusCode, nil, errors.New("member response is unreadable or oversized")
	}
	return response.StatusCode, data, nil
}

